INSERT INTO faq_documents (title, content, source, category)
SELECT 'Đau đầu như thế nào là dấu hiệu cảnh báo của bệnh u não?', 'Đau đầu do u não thường diễn ra thường xuyên, mức độ đau dữ dội và có xu hướng tăng dần theo thời gian, đặc biệt đau nhiều hơn vào buổi sáng sớm sau khi ngủ dậy. Nguyên nhân là do khối u phát triển choán chỗ trong hộp sọ gây tăng áp lực nội sọ.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Đau đầu như thế nào là dấu hiệu cảnh báo của bệnh u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Uống thuốc giảm đau thông thường không đỡ đau đầu vào buổi sáng thì có đáng lo không?', 'Rất đáng lo ngại. Khác với đau đầu do căng thẳng thường dịu đi khi uống thuốc giảm đau, đau đầu do khối u chèn ép tăng áp lực nội sọ thường dữ dội nhất lúc thức dậy và rất kém đáp ứng với các loại thuốc giảm đau thông thường. Nếu bạn đau đầu buổi sáng kéo dài trên 1-2 tuần, cần đi khám chuyên khoa thần kinh ngay.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Uống thuốc giảm đau thông thường không đỡ đau đầu vào buổi sáng thì có đáng lo không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Buồn nôn và nôn mửa liên quan gì đến bệnh u não?', 'Buồn nôn hoặc nôn mửa do u não xuất phát từ việc tăng áp lực trong sọ não kích thích trung tâm nôn, thường xảy ra rõ rệt nhất vào buổi sáng sau khi thức dậy kèm cảm giác mệt mỏi, suy kiệt. Khác với bệnh lý tiêu hóa, nôn do u não thường đi kèm đau đầu liên tục tăng dần mà không liên quan đến bữa ăn.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Buồn nôn và nôn mửa liên quan gì đến bệnh u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Làm sao phân biệt nôn mửa do bệnh tiêu hóa với nôn mửa do u não?', 'Nôn do bệnh tiêu hóa (như đau dạ dày, ngộ độc) thường kèm theo đau quặn bụng, ợ hơi, tiêu chảy và đỡ buồn nôn sau khi nôn. Trong khi đó, nôn do u não là nôn vọt (nôn đột ngột không báo trước), thường xảy ra lúc sáng sớm khi dạ dày rỗng, kèm theo đau đầu dữ dội và sau khi nôn xong cơn đau đầu vẫn không thuyên giảm.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Làm sao phân biệt nôn mửa do bệnh tiêu hóa với nôn mửa do u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U não có thể gây ra những rối loạn gì về thị giác và thính giác?', 'Khi khối u não phát triển chèn ép các dây thần kinh sọ hoặc trung tâm dẫn truyền, người bệnh có thể bị suy giảm thính lực, khó nghe, ù tai, hoặc mắt mờ, nhìn đôi (song thị - nhìn một vật thành hai), tầm nhìn thu hẹp dần.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U não có thể gây ra những rối loạn gì về thị giác và thính giác?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hiện tượng nhìn đôi (nhìn 1 vật thành 2) cảnh báo u não ở vị trí nào?', 'Nhìn đôi (song thị) thường xuất hiện khi khối u chèn ép các dây thần kinh vận nhãn (dây số III, IV, VI) hoặc u vùng tuyến yên, thân não, góc cầu - tiểu não. Khối u làm liệt cơ vận nhãn khiến hai mắt không cùng nhìn về một hướng, gây nhìn một thành hai, đặc biệt rõ khi liếc sang một bên.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hiện tượng nhìn đôi (nhìn 1 vật thành 2) cảnh báo u não ở vị trí nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Ù tai liên tục kèm giảm thính lực một bên tai có phải do u não không?', 'Ù tai dạng tiếng ve kêu hoặc tiếng gió rít kéo dài, đi kèm giảm khả năng nghe ở một bên tai là triệu chứng điển hình của u bao dây thần kinh thính giác (U dây thần kinh số VIII hoặc u góc cầu tiểu não). Nếu bạn thấy nghe điện thoại bằng một bên tai ngày càng kém rõ rệt, cần chụp MRI sọ não để kiểm tra.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Ù tai liên tục kèm giảm thính lực một bên tai có phải do u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao người bị u não lại bị nói khó, nói lắp?', 'Nếu khối u nằm ở mặt sau hoặc các vùng chi phối ngôn ngữ của não bộ (vùng Broca, Wernicke ở bán cầu ưu thế), chức năng truyền đạt tín hiệu phát âm và hiểu ngôn ngữ sẽ bị suy giảm, dẫn đến tình trạng nói khó, nói ngọng, nói lắp hoặc người bệnh hiểu nhưng không thể nói ra thành lời.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao người bị u não lại bị nói khó, nói lắp?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Đột ngột khó tìm từ diễn đạt hoặc không hiểu lời người khác nói có liên quan u não không?', 'Có. Đây là hội chứng mất ngôn ngữ (aphasia). Khối u chèn ép vùng thái dương hoặc vùng trán trái có thể khiến người bệnh quên tên các đồ vật quen thuộc, dùng từ lộn xộn hoặc không hiểu người đối diện nói gì dù tai vẫn nghe rõ. Hiện tượng này cần được phân biệt khẩn trương giữa đột quỵ não và u não.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Đột ngột khó tìm từ diễn đạt hoặc không hiểu lời người khác nói có liên quan u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Yếu liệt tay chân ở người bệnh u não có đặc điểm gì?', 'Người bệnh cảm giác cánh tay và chân mất dần sức lực, yếu đi rõ rệt, hay làm rơi đồ vật hoặc đi dép dễ bị tuột. Do đường dẫn truyền thần kinh vận động bắt chéo, khối u ở bán cầu não phải sẽ gây yếu tay chân bên trái, và ngược lại khối u ở não trái sẽ làm suy yếu tay chân bên phải.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Yếu liệt tay chân ở người bệnh u não có đặc điểm gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Cầm đũa hay rơi hoặc viết chữ nguệch ngoạc dần có phải dấu hiệu cảnh báo u não?', 'Đúng, đó là dấu hiệu yếu cơ tinh vi và suy giảm vận động khéo léo của bàn tay do khối u chèn ép dải vỏ gai vận động ở thùy trán. Khi thấy một bên bàn tay tự nhiên vụng về, cài khuy áo khó khăn, cầm bút hay bát đũa dễ rơi rớt, người bệnh không nên chủ quan nghĩ là thoái hóa xương khớp.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Cầm đũa hay rơi hoặc viết chữ nguệch ngoạc dần có phải dấu hiệu cảnh báo u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Biểu hiện lú lẫn, hay quên ở người bị u não xuất hiện ở giai đoạn nào?', 'Biểu hiện lú lẫn, thường xuyên nhầm lẫn, suy giảm trí nhớ (quên quên, nhớ nhớ) thường xuất hiện ở giai đoạn muộn của bệnh khi khối u đã choán chỗ lớn gây tăng áp lực nội sọ diện rộng hoặc xâm lấn sâu vào các thùy chức năng tư duy và cảm xúc.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Biểu hiện lú lẫn, hay quên ở người bị u não xuất hiện ở giai đoạn nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khối u não ở vị trí nào gây mất thăng bằng và đi lại khó khăn?', 'Nếu khối u xuất hiện ở mặt sau não (đặc biệt là vùng tiểu não - trung tâm phối hợp vận động và giữ thăng bằng), người bệnh sẽ bị choáng váng, đi đứng loạng choạng như người say rượu, bước chân không vững và rất khó khăn khi tự di chuyển.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khối u não ở vị trí nào gây mất thăng bằng và đi lại khó khăn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Làm sao phân biệt chóng mặt mất thăng bằng do tiền đình với do u tiểu não?', 'Chóng mặt tiền đình thường xuất hiện từng cơn dữ dội khi thay đổi tư thế đầu, kèm hoa mắt quay cuồng nhưng không liệt chi. Ngược lại, mất thăng bằng do u tiểu não diễn biến từ từ, người bệnh đi loạng choạng liên tục, run tay khi với đồ vật, khó chạm ngón tay vào đầu mũi và mức độ mất thăng bằng tăng dần theo thời gian.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Làm sao phân biệt chóng mặt mất thăng bằng do tiền đình với do u tiểu não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Cơn co giật, động kinh do u não có phải là dấu hiệu nguy hiểm khẩn cấp không?', 'Đúng, động kinh là dấu hiệu cảnh báo nghiêm trọng do khối u kích thích trực tiếp lên vỏ não làm phóng điện bất thường. Bất kỳ cơn co giật nào xuất hiện lần đầu ở người trưởng thành đều là tình huống khẩn cấp cần được đưa đến cơ sở y tế cấp cứu ngay.', 'Vinmec — Triệu chứng cảnh báo u não và cách điều trị (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Cơn co giật, động kinh do u não có phải là dấu hiệu nguy hiểm khẩn cấp không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Co giật do u não có biểu hiện như thế nào? Chỉ giật một tay có phải động kinh không?', 'Co giật do u não có thể là cơn cục bộ (chỉ co giật, giật cơ ở một ngón tay, một cánh tay hoặc co giật nửa mặt trong vài giây đến vài phút) hoặc cơn toàn thể (co giật toàn thân, trợn mắt, sùi bọt mép và mất ý thức). Giật cục bộ tái diễn một bên chi là dấu hiệu định khu rất rõ của tổn thương não đối bên.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Co giật do u não có biểu hiện như thế nào? Chỉ giật một tay có phải động kinh không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Cần xử trí sơ cứu thế nào tại chỗ khi người bệnh u não bị lên cơn co giật?', 'Khi người bệnh co giật: (1) Đặt người bệnh nằm nghiêng sang một bên nơi an toàn, thoáng mát để đờm dãi chảy ra, tránh sặc vào đường thở; (2) Kê vật mềm dưới đầu; (3) Tuyệt đối KHÔNG nhét khăn, thìa hay ngón tay vào miệng người bệnh; (4) Nới lỏng cổ áo và gọi xe cấp cứu 115 đưa đến bệnh viện ngay.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Cần xử trí sơ cứu thế nào tại chỗ khi người bệnh u não bị lên cơn co giật?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khi u não tiến triển nặng, trí năng và ý thức bị ảnh hưởng nghiêm trọng như thế nào?', 'Khi khối u não diễn tiến nặng, người bệnh bị suy giảm trí năng sâu sắc: mất khả năng tập trung, sa sút trí nhớ nghiêm trọng, hành vi và cảm xúc bất ổn, lơ mơ, ngủ gà và có thể dẫn đến mất hoàn toàn ý thức (hôn mê). Đây là dấu hiệu nguy cấp do tăng áp lực nội sọ đe dọa tụt não.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khi u não tiến triển nặng, trí năng và ý thức bị ảnh hưởng nghiêm trọng như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Biểu hiện hành vi bất ổn và thay đổi cảm xúc ở bệnh nhân u não diễn tiến nặng ra sao?', 'Người bệnh có thể có các hành vi mất kiềm chế, thờ ơ lãnh đạm với xung quanh, hoặc ngược lại trở nên kích động, hoang tưởng, lo âu quá mức. Những thay đổi này là do tổn thương thực thể ở mạng lưới dẫn truyền cảm xúc của thùy trán và hệ viền, không phải do bệnh nhân cố tình.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Biểu hiện hành vi bất ổn và thay đổi cảm xúc ở bệnh nhân u não diễn tiến nặng ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hiện tượng suy giảm đa giác quan và vận động ở giai đoạn nặng của u não biểu hiện ra sao?', 'Ở giai đoạn nặng, khối u xâm lấn nhiều đường dẫn truyền thần kinh gây suy giảm đa giác quan: mắt mờ, nhạy cảm quá mức với ánh sáng, mất vị giác, mất khứu giác, tê bì chân tay, yếu một phần chi cho đến liệt nửa người hoặc co giật tái diễn.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hiện tượng suy giảm đa giác quan và vận động ở giai đoạn nặng của u não biểu hiện ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nhạy cảm với ánh sáng (sợ ánh sáng, chói mắt) có phải triệu chứng của u não?', 'Đúng. Hiện tượng nhạy cảm quá mức với ánh sáng (photophobia) thường xảy ra khi tăng áp lực trong sọ gây kích thích màng não, hoặc do khối u chèn ép giao thoa thị giác làm phù gai thị. Người bệnh cảm thấy chói mắt dữ dội, đau nhức đầu tăng lên khi nhìn vào ánh đèn sáng hoặc ánh nắng.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nhạy cảm với ánh sáng (sợ ánh sáng, chói mắt) có phải triệu chứng của u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Mất khứu giác (không ngửi thấy mùi) hoặc mất vị giác có liên quan đến u não không?', 'Mất khứu giác một hoặc hai bên là dấu hiệu chỉ điểm quan trọng của các khối u rãnh khứu giác (u màng não rãnh khứu) hoặc u thùy trán chèn ép dải khứu giác. Tương tự, rối loạn hoặc mất vị giác có thể do tổn thương dây thần kinh số VII, IX hoặc vùng vỏ não cảm giác thùy đỉnh.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Mất khứu giác (không ngửi thấy mùi) hoặc mất vị giác có liên quan đến u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tê bì chân tay hoặc cảm giác châm chích như kiến bò một bên người cảnh báo điều gì?', 'Cảm giác tê bì, mất cảm giác đau/nóng/lạnh hoặc dị cảm như kiến bò kéo dài ở một bên tay, chân hoặc nửa mặt là biểu hiện của việc khối u chèn ép hồi đỉnh sau (vùng vỏ não cảm giác thân thể) hoặc các dây thần kinh cảm giác sọ não. Hiện tượng này cần được khám thần kinh sớm.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tê bì chân tay hoặc cảm giác châm chích như kiến bò một bên người cảnh báo điều gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Liệt nửa người do khối u não diễn tiến như thế nào? Khác gì với liệt do tai biến mạch máu não?', 'Liệt do tai biến mạch máu não (đột quỵ) thường xảy ra đột ngột chỉ trong vài phút đến vài giờ. Ngược lại, liệt do u não diễn tiến từ từ trong nhiều tuần đến nhiều tháng: ban đầu chỉ là cảm giác yếu, nặng chân tay hoặc vụng về khi vận động, sau đó mức độ yếu tăng dần thành liệt nửa người kèm theo đau đầu dữ dội.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Liệt nửa người do khối u não diễn tiến như thế nào? Khác gì với liệt do tai biến mạch máu não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U não có thể gây ra những rối loạn chức năng sinh học nào trong cơ thể?', 'Do khối u làm ảnh hưởng đến trung tâm thần kinh thực vật và điều hòa nội tiết trong não, người bệnh có thể gặp các rối loạn sinh học như: huyết áp hạ thấp, mất ngủ kéo dài, tâm lý lo âu bất ổn và cơ thể trở nên đặc biệt nhạy cảm với sự thay đổi nhiệt độ nóng/lạnh.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U não có thể gây ra những rối loạn chức năng sinh học nào trong cơ thể?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Mất ngủ kéo dài kèm theo tâm lý bất ổn, lo âu có thể là do u não không?', 'Có thể. Khối u chèn ép vùng dưới đồi, tuyến tùng (nơi tiết melatonin điều hòa chu kỳ thức - ngủ) hoặc làm tăng áp lực sọ não về đêm sẽ gây mất ngủ trầm trọng, tỉnh giấc nửa đêm kèm đau đầu. Sự xáo trộn này khiến người bệnh dễ rơi vào trạng thái tâm lý bất ổn, cáu kỉnh hoặc trầm cảm.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Mất ngủ kéo dài kèm theo tâm lý bất ổn, lo âu có thể là do u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao người bệnh u não lại trở nên đặc biệt nhạy cảm với nhiệt độ nóng lạnh?', 'Vùng dưới đồi (Hypothalamus) ở trung tâm não bộ đóng vai trò như ''bộ điều nhiệt'' của cơ thể. Khi khối u phát triển ở khu vực này hoặc gây phù nề chèn ép lân cận, khả năng điều hòa thân nhiệt sẽ bị rối loạn, khiến người bệnh cực kỳ nhạy cảm, dễ bị rét run dù trời ấm hoặc bốc hỏa, vã mồ hôi bất thường.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao người bệnh u não lại trở nên đặc biệt nhạy cảm với nhiệt độ nóng lạnh?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Huyết áp thấp kèm người mệt mỏi rã rời không có sức lực cảnh báo u não vùng nào?', 'Hạ huyết áp tư thế kèm mệt mỏi uể oải, mất hết sức lực thường xuất hiện khi khối u chèn ép tuyến yên hoặc thân não làm suy giảm hormone vỏ thượng thận (ACTH) hoặc rối loạn phản xạ vận mạch thực vật. Khi đau đầu kèm huyết áp tụt liên tục, bệnh nhân cần được làm xét nghiệm nội tiết và chụp MRI sọ não.', 'Bệnh viện Đa khoa Tâm Anh — U não: Chẩn đoán & điều trị hiệu quả bằng phương pháp hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'symptoms'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Huyết áp thấp kèm người mệt mỏi rã rời không có sức lực cảnh báo u não vùng nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Meningioma (U màng não) là gì? Khối u này bắt nguồn từ đâu?', 'Meningioma là loại u phát triển từ màng não (meninges) — các lớp màng mô mỏng có nhiệm vụ bao bọc và bảo vệ não bộ cũng như tủy sống. Đây là dạng u não nguyên phát phổ biến nhất ở người trưởng thành, chiếm khoảng 30% tổng số ca u não. Đa số các trường hợp gặp ở độ tuổi 30-50 và phụ nữ có tỷ lệ mắc cao gấp 2-3 lần nam giới.', 'Nhà thuốc Long Châu & Johns Hopkins Medicine — Meningioma là gì? Những tác động của Meningioma đến sức khỏe (https://nhathuoclongchau.com.vn/bai-viet/meningioma-la-gi-nhung-tac-dong-cua-meningioma-den-suc-khoe.html)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Meningioma (U màng não) là gì? Khối u này bắt nguồn từ đâu?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U màng não thường là u lành tính hay ác tính?', 'May mắn là phần lớn u màng não (khoảng 80% - 90%) là u lành tính (Cấp độ 1 theo WHO), phát triển rất chậm trong nhiều năm hoặc thậm chí nhiều thập kỷ mà không có biểu hiện. Chỉ khoảng 10% là u màng não không điển hình (Độ 2) hoặc ác tính (Độ 3) có khả năng xâm lấn mô não lân cận và tái phát nhanh hơn.', 'Nhà thuốc Long Châu & Johns Hopkins Medicine — Phân loại và đặc điểm mô bệnh học u màng não (https://nhathuoclongchau.com.vn/bai-viet/meningioma-la-gi-nhung-tac-dong-cua-meningioma-den-suc-khoe.html)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U màng não thường là u lành tính hay ác tính?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khối u ''ngoài trục'' (extra-axial) của u màng não có ý nghĩa thế nào với việc điều trị?', 'U ngoài trục có nghĩa là khối u không xuất phát từ bên trong nhu mô não, mà ép vào bề mặt não từ màng cứng bên ngoài. Do đó, u màng não thường có ranh giới phân tách rõ ràng với các mô não lành xung quanh, tạo điều kiện thuận lợi cho phẫu thuật viên bóc tách triệt để khối u với độ an toàn cao hơn so với các u nằm sâu trong trục não.', 'Johns Hopkins Medicine — Meningioma: Types, Diagnosis, and Treatment Options (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khối u ''ngoài trục'' (extra-axial) của u màng não có ý nghĩa thế nào với việc điều trị?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Dấu hiệu ''đuôi màng cứng'' (dural tail) trên phim chụp MRI của u màng não là gì?', 'Trên phim chụp cộng hưởng từ (MRI) có tiêm thuốc cản quang, dấu hiệu ''đuôi màng cứng'' là hình ảnh phần màng não liền kề khối u ngấm thuốc đậm tạo thành một vệt dài như chiếc đuôi sam. Đây là dấu hiệu hình ảnh kinh điển giúp các bác sĩ và mô hình AI phân biệt u màng não với các khối u nội sọ khác.', 'Johns Hopkins Medicine — MRI Features of Meningioma with Dural Tail Sign (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Dấu hiệu ''đuôi màng cứng'' (dural tail) trên phim chụp MRI của u màng não là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao phụ nữ lại có nguy cơ mắc u màng não cao gấp 2 đến 3 lần nam giới?', 'Các nhà khoa học phát hiện tế bào u màng não thường chứa nhiều thụ thể tiếp nhận hormone sinh dục nữ (đặc biệt là Progesterone và Estrogen). Nồng độ hormone dao động trong thai kỳ, chu kỳ kinh nguyệt hoặc liệu pháp thay thế hormone sau mãn kinh có thể kích thích tế bào u tăng sinh, khiến tỷ lệ phụ nữ mắc bệnh cao hơn rõ rệt.', 'Nhà thuốc Long Châu & Johns Hopkins Medicine — Yếu tố hormone trong sự phát triển của u màng não (https://nhathuoclongchau.com.vn/bai-viet/meningioma-la-gi-nhung-tac-dong-cua-meningioma-den-suc-khoe.html)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao phụ nữ lại có nguy cơ mắc u màng não cao gấp 2 đến 3 lần nam giới?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U màng não phát hiện tình cờ khi đi khám sức khỏe, không có triệu chứng thì xử trí sao?', 'Nếu u màng não có kích thước nhỏ, nằm ở vị trí không đe dọa các dây thần kinh sọ và không gây phù não, phương án tối ưu thường là ''theo dõi thận trọng'' (watchful waiting). Bác sĩ sẽ hẹn bạn chụp lại MRI định kỳ mỗi 6 đến 12 tháng để đánh giá tốc độ phát triển trước khi quyết định can thiệp phẫu thuật hay xạ phẫu.', 'Johns Hopkins Medicine — Watchful Waiting for Asymptomatic Meningioma (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U màng não phát hiện tình cờ khi đi khám sức khỏe, không có triệu chứng thì xử trí sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Glioma (U tế bào thần kinh đệm) là gì? Tế bào đệm có vai trò gì trong não?', 'Glioma là nhóm u não nguyên phát xuất phát từ các tế bào thần kinh đệm (glial cells). Tế bào đệm là hệ thống các tế bào phụ trợ có vai trò nuôi dưỡng, dọn dẹp chuyển hóa và bảo vệ các neuron thần kinh. Glioma là dạng u não ác tính phổ biến nhất hiện nay, chiếm khoảng 74% trong tổng số các ca u não ác tính.', 'Đông y Sơn Hà & Mayo Clinic — U tế bào thần kinh đệm: Nguyên nhân, phân loại và điều trị (https://dongysonha.com.vn/u-than-kinh-dem/)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Glioma (U tế bào thần kinh đệm) là gì? Tế bào đệm có vai trò gì trong não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tổ chức Y tế Thế giới (WHO) phân loại các cấp độ của Glioma như thế nào?', 'WHO phân chia Glioma từ Cấp độ 1 đến Cấp độ 4: Cấp độ thấp (Độ 1 và 2 như u tế bào hình sao - astrocytoma, u nguyên bào ít nhánh - oligodendroglioma) phát triển chậm, ít xâm lấn; Cấp độ cao (Độ 3 và 4) là các khối u ác tính phát triển nhanh, thâm nhiễm lan tỏa vào mô não lành xung quanh và có tiên lượng phức tạp.', 'Tisch Brain Tumor Center - Duke University — What is a Glioma Brain Tumor? Everything You Need to Know (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tổ chức Y tế Thế giới (WHO) phân loại các cấp độ của Glioma như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Glioblastoma (u nguyên bào thần kinh đệm đa hình thái - GBM) nguy hiểm thế nào?', 'Glioblastoma là Glioma Cấp độ 4 (cấp cao nhất), là dạng ung thư não nguyên phát phổ biến nhất và dữ dội nhất ở người trưởng thành. Tế bào khối u phân chia cực nhanh, tự tạo mạng lưới tân mạch để nuôi u và thâm nhiễm sâu vào các sợi trục thần kinh. Bệnh nhân cần được can thiệp điều trị khẩn trương tại các trung tâm ngoại thần kinh chuyên sâu.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Glioblastoma Multiforme Characteristics and Clinical Aggressiveness (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Glioblastoma (u nguyên bào thần kinh đệm đa hình thái - GBM) nguy hiểm thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tính chất u ''trong trục'' và xâm lấn lan tỏa của Glioma ảnh hưởng gì đến phẫu thuật?', 'Khác với u màng não, Glioma là khối u ''trong trục'' (sinh ra và phát triển trực tiếp ngay trong nhu mô não). U không có vỏ bọc ranh giới rõ ràng mà đan xen với các tế bào não khỏe mạnh và gây phù nề rộng. Do đó, việc mổ lấy u đòi hỏi phẫu thuật viên phải cân bằng giữa việc cắt bỏ tối đa khối u và bảo tồn các vùng chức năng nói, vận động của người bệnh.', 'Mayo Clinic — Glioma Overview: Infiltrative Nature and Surgical Challenges (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tính chất u ''trong trục'' và xâm lấn lan tỏa của Glioma ảnh hưởng gì đến phẫu thuật?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Đột biến IDH và mất đoạn 1p/19q trong chẩn đoán sinh học phân tử Glioma là gì?', 'Theo chuẩn phân loại mới nhất của WHO và Mayo Clinic, chẩn đoán Glioma bắt buộc dựa vào dấu ấn phân tử: U có đột biến gen IDH (IDH-mutant) thường có tiên lượng tốt hơn và đáp ứng điều trị cao hơn u mang gen IDH bình thường (IDH-wildtype). Mất đồng thời cánh ngắn nhiễm sắc thể 1 và cánh dài 19 (mất đoạn 1p/19q co-deletion) là dấu hiệu xác thực của u nguyên bào ít nhánh.', 'Mayo Clinic — Molecular Classification of Gliomas: IDH and 1p/19q Status (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Đột biến IDH và mất đoạn 1p/19q trong chẩn đoán sinh học phân tử Glioma là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Các triệu chứng lâm sàng thường gặp nhất khi có khối u Glioma là gì?', 'Người bệnh Glioma thường có 6 nhóm triệu chứng điển hình: Đau đầu (đặc biệt dữ dội vào buổi sáng khi ngủ dậy do tăng áp lực nội sọ), buồn nôn và nôn ói, xuất hiện cơn co giật động kinh, yếu liệt tay chân hoặc khó vận động, thay đổi tính cách/lú lẫn sa sút trí nhớ và rối loạn thị giác (nhìn mờ, nhìn đôi).', 'Tisch Brain Tumor Center - Duke University — Common Symptoms and Warning Signs of Glioma (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Các triệu chứng lâm sàng thường gặp nhất khi có khối u Glioma là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Các phương pháp điều trị chuẩn hiện nay cho người bệnh Glioma bao gồm những gì?', 'Điều trị Glioma đòi hỏi phối hợp đa mô thức: (1) Phẫu thuật cắt bỏ tối đa khối u an toàn; (2) Xạ trị vào vùng giường u sau mổ; (3) Hóa trị bằng thuốc viên Temozolomide (phác đồ Stupp) giúp tiêu diệt các tế bào ung thư sót lại; và (4) Liệu pháp nhắm trúng đích, xạ phẫu kết hợp phục hồi chức năng và chăm sóc giảm nhẹ.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Multimodal Treatment for Malignant Gliomas (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Các phương pháp điều trị chuẩn hiện nay cho người bệnh Glioma bao gồm những gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tuyến yên là gì và u tuyến yên (Pituitary Tumor) xuất hiện ở đâu?', 'Tuyến yên là một tuyến nội tiết có kích thước nhỏ như hạt đậu, nằm trong hố yên bằng xương ở đáy hộp sọ (ngay dưới não và phía sau sống mũi). Dù nhỏ bé, tuyến yên được coi là ''nhạc trưởng'' vì sản xuất và giải phóng hormone kiểm soát hoạt động của tuyến giáp, tuyến thượng thận và buồng trứng/tinh hoàn. U tuyến yên là sự tăng sinh bất thường của các tế bào tại tuyến này.', 'Cleveland Clinic — Pituitary Adenomas: Overview, Symptoms and Function (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tuyến yên là gì và u tuyến yên (Pituitary Tumor) xuất hiện ở đâu?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U tuyến yên có phải là ung thư không? Có di căn sang nơi khác không?', 'Đại đa số u tuyến yên (trên 99%) là u tuyến lành tính (Pituitary Adenoma). Khối u này phát triển cục bộ tại hố yên đáy não, không phải là ung thư và không có khả năng di căn xa tới các cơ quan khác trong cơ thể. Tuy nhiên, khi u phát triển to có thể chèn ép các cấu trúc thần kinh lân cận đe dọa thị giác của người bệnh.', 'Cleveland Clinic — Benign Nature of Pituitary Adenomas (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U tuyến yên có phải là ung thư không? Có di căn sang nơi khác không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phân biệt u tuyến yên chức năng và u tuyến yên không chức năng như thế nào?', 'U tuyến yên được chia làm 2 nhóm chính: (1) U chức năng (Functioning): Các tế bào khối u tự động bài tiết hormone quá mức gây rối loạn chuyển hóa; (2) U không chức năng (Non-functioning): Khối u không sản xuất hormone, thường tiến triển âm thầm cho đến khi kích thước lớn chèn ép giao thoa thị giác gây mờ mắt và đau đầu.', 'Cleveland Clinic — Functioning vs Nonfunctioning Pituitary Tumors (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phân biệt u tuyến yên chức năng và u tuyến yên không chức năng như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U tuyến yên gây ra những hội chứng rối loạn nội tiết điển hình nào?', 'Tùy loại hormone bị tăng tiết, u tuyến yên có thể gây: (1) Bệnh to đầu chi (Acromegaly) do thừa hormone tăng trưởng GH, làm to bàn tay, bàn chân, xương hàm dưới nhô ra; (2) Hội chứng Cushing do thừa ACTH, gây mặt tròn như mặt trăng, béo bụng, rạn da đỏ; (3) U tiết Prolactin (Prolactinoma) gây tiết sữa bất thường, vô kinh ở phụ nữ và giảm ham muốn ở nam giới.', 'Cleveland Clinic — Endocrine Syndromes Caused by Pituitary Tumors (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U tuyến yên gây ra những hội chứng rối loạn nội tiết điển hình nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao u tuyến yên lại gây giảm thị lực và bán manh hai bên thái dương (mờ rìa mắt)?', 'Giao thoa thị giác (nơi hai dây thần kinh thị giác bắt chéo nhau) nằm ngay phía trên tuyến yên. Khi khối u phát triển kích thước lớn (Macroadenoma >1cm) đội lên trên sẽ đè nén vào trung tâm giao thoa thị giác, làm gián đoạn các sợi thần kinh dẫn truyền từ thị trường ngoại vi, dẫn đến hiện tượng bán manh hai bên thái dương (nhìn như bị thu hẹp góc nhìn sang hai bên rìa).', 'Cleveland Clinic — Vision Changes and Optic Chiasm Compression in Pituitary Tumors (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao u tuyến yên lại gây giảm thị lực và bán manh hai bên thái dương (mờ rìa mắt)?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nhãn ''No Tumor'' trong hệ thống chẩn đoán u não AI có ý nghĩa gì?', 'Nhãn ''No Tumor'' xác nhận rằng trên ảnh chụp MRI não bạn đã tải lên, mô hình AI không phát hiện bất kỳ dấu hiệu bệnh học đặc trưng nào của 3 nhóm u não (Glioma, Meningioma, Pituitary). Cấu trúc nhu mô não, rãnh cuộn não và kích thước hố yên đều nằm trong giới hạn hình ảnh bình thường của tập đối chứng.', 'Khuyến cáo chuyên môn dự án AI chẩn đoán MRI — Diễn giải nhãn phân loại No Tumor trên hệ thống hỗ trợ chẩn đoán (https://moh.gov.vn)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nhãn ''No Tumor'' trong hệ thống chẩn đoán u não AI có ý nghĩa gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nếu kết quả AI báo ''No Tumor'' nhưng tôi vẫn bị đau đầu liên tục thì nên làm gì?', 'Kết quả AI không thay thế được chẩn đoán lâm sàng của bác sĩ. Đau đầu có thể do rất nhiều nguyên nhân khác không tạo thành khối u trên MRI cắt lớp đơn lẻ (như viêm xoang, co cứng cơ cổ vai gáy, thiếu máu não thoáng qua hoặc đau nửa đầu Migraine). Bạn nên mang toàn bộ file chụp gốc đến bệnh viện để bác sĩ chuyên khoa thần kinh khám trực tiếp và tư vấn phác đồ điều trị.', 'Khuyến cáo chuyên môn dự án AI chẩn đoán MRI — Hướng dẫn người bệnh khi có kết quả chẩn đoán hình ảnh âm tính (https://moh.gov.vn)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nếu kết quả AI báo ''No Tumor'' nhưng tôi vẫn bị đau đầu liên tục thì nên làm gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khối u màng não kích thước bao nhiêu thì được coi là nguy hiểm và cần phẫu thuật gấp?', 'U màng não dưới 2-3cm nếu không gây triệu chứng thường chỉ cần theo dõi định kỳ. Tuy nhiên, khi khối u đạt kích thước trên 3-4cm, gây phù nề nhu mô não xung quanh, đè bẹp não thất hoặc đẩy lệch đường giữa đe dọa tụt não thì được coi là nguy hiểm và cần can thiệp phẫu thuật sớm để giải tỏa chèn ép.', 'Johns Hopkins Medicine — Meningioma Size, Symptoms and Surgical Indications (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khối u màng não kích thước bao nhiêu thì được coi là nguy hiểm và cần phẫu thuật gấp?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh có thể sống chung hòa bình với khối u màng não lành tính suốt đời mà không cần mổ không?', 'Hoàn toàn có thể. Rất nhiều người bệnh (đặc biệt là người cao tuổi) sống chung khỏe mạnh suốt đời với khối u màng não nhỏ, phát triển cực kỳ chậm mà không cần bất kỳ can thiệp phẫu thuật nào. Người bệnh chỉ cần duy trì lịch tái khám chụp MRI định kỳ mỗi năm một lần để theo dõi kích thước u.', 'Nhà thuốc Long Châu & Johns Hopkins — Sống chung an toàn với khối u màng não lành tính (https://nhathuoclongchau.com.vn/bai-viet/meningioma-la-gi-nhung-tac-dong-cua-meningioma-den-suc-khoe.html)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh có thể sống chung hòa bình với khối u màng não lành tính suốt đời mà không cần mổ không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khối u màng não lành tính có khi nào bị biến đổi thành ung thư ác tính không?', 'Tỷ lệ một khối u màng não lành tính (Độ 1) thoái hóa thành u ác tính là cực kỳ hiếm, ước tính chỉ khoảng 1-2% trong suốt quá trình theo dõi lâu dài. Đa phần các khối u màng não giữ nguyên bản chất mô bệnh học lành tính từ khi hình thành cho đến cuối đời.', 'Johns Hopkins Medicine — Risk of Malignant Transformation in Benign Meningioma (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khối u màng não lành tính có khi nào bị biến đổi thành ung thư ác tính không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bác sĩ chẩn đoán u màng não nằm ở nền sọ thì mức độ nguy hiểm và độ khó phẫu thuật ra sao?', 'U màng não vùng nền sọ (như rãnh khứu, cánh xương bướm, góc cầu tiểu não) được coi là vị trí phức tạp vì nằm sát các dây thần kinh sọ quan trọng (thị giác, thính giác, vận nhãn) và các động mạch lớn nuôi não. Mổ vị trí này đòi hỏi trang thiết bị vi phẫu định vị 3D hiện đại hoặc phối hợp xạ phẫu Dao Gamma để bảo tồn tối đa chức năng thần kinh.', 'Bệnh viện Hữu nghị Việt Đức & Johns Hopkins — Phẫu thuật u màng não vùng nền sọ phức tạp (https://benhvienvietduc.org)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bác sĩ chẩn đoán u màng não nằm ở nền sọ thì mức độ nguy hiểm và độ khó phẫu thuật ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phụ nữ bị u màng não có được mang thai hoặc dùng thuốc tránh thai nội tiết không?', 'Do tế bào u màng não thường có nhiều thụ thể tiếp nhận hormone progesterone và estrogen, khối u có nguy cơ phát triển kích thước nhanh hơn trong thai kỳ hoặc khi dùng thuốc tránh thai nội tiết liều cao. Phụ nữ phát hiện u màng não cần tham khảo ý kiến bác sĩ chuyên khoa thần kinh để được tư vấn phương pháp tránh thai không nội tiết an toàn và theo dõi sát nếu có kế hoạch mang thai.', 'Nhà thuốc Long Châu & Johns Hopkins — Ảnh hưởng của thai kỳ và thuốc nội tiết đến u màng não (https://nhathuoclongchau.com.vn/bai-viet/meningioma-la-gi-nhung-tac-dong-cua-meningioma-den-suc-khoe.html)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phụ nữ bị u màng não có được mang thai hoặc dùng thuốc tránh thai nội tiết không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao bác sĩ lại giải thích là khối u thần kinh đệm (Glioma) rất khó mổ sạch 100% chân u?', 'Bản chất sinh học của Glioma là u xâm lấn lan tỏa (infiltrative). Các tế bào u đâm nhánh len lỏi vào giữa các nơ-ron não khỏe mạnh giống như rễ cây ăn sâu vào lòng đất chứ không có lớp vỏ bọc phân tách. Nếu cố cắt rộng để hết sạch tế bào u vi thể, người bệnh sẽ bị tổn thương các vùng não lành dẫn đến liệt hoặc mất tiếng nói.', 'Mayo Clinic & Tisch Brain Tumor Center — Why Infiltrative Gliomas Cannot Be Completely Resected (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao bác sĩ lại giải thích là khối u thần kinh đệm (Glioma) rất khó mổ sạch 100% chân u?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau khi mổ và xạ trị u Glioma, tại sao khối u vẫn có nguy cơ tái phát trở lại?', 'Dù phẫu thuật đã lấy hết phần u nhìn thấy trên mắt thường và MRI, một số tế bào u vi thể kháng thuốc vẫn có thể ''ngủ đông'' rải rác trong nhu mô não lân cận. Sau một thời gian, các tế bào này kích hoạt tăng sinh mạch máu mới và phát triển tái phát, đó là lý do người bệnh cần theo dõi chụp MRI định kỳ mỗi 3-6 tháng để phát hiện sớm.', 'Tisch Brain Tumor Center - Duke University — Recurrence Mechanisms in High-Grade Gliomas (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau khi mổ và xạ trị u Glioma, tại sao khối u vẫn có nguy cơ tái phát trở lại?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U não Glioma có bị di căn xuống các cơ quan khác như phổi, gan, xương không?', 'Rất may mắn là Glioma gần như không bao giờ di căn xa ra các cơ quan ngoài não bộ như phổi, xương hay gan (chiếm tỷ lệ dưới 0.1%), nhờ có hệ thống hàng rào máu não ngăn chặn. Nguy cơ chính của bệnh chỉ khu trú tại hộp sọ là tái phát và xâm lấn phá hủy mô não lân cận.', 'Mayo Clinic — Do Brain Tumors Spread to Other Parts of the Body? (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U não Glioma có bị di căn xuống các cơ quan khác như phổi, gan, xương không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bệnh nhân mắc Glioma Cấp độ 3 hoặc 4 (Glioblastoma) thì thời gian sống thêm và tiên lượng ra sao?', 'Tiên lượng sống phụ thuộc rất lớn vào tuổi tác, thể trạng, mức độ cắt bỏ khối u và xét nghiệm đột biến gen IDH/methyl hóa MGMT. Mặc dù Glioblastoma là bệnh lý hiểm nghèo với thời gian sống trung bình 15-24 tháng theo y văn, nhưng hiện nay nhiều bệnh nhân đáp ứng thuốc hóa trị tốt đã kéo dài thời gian sống trên 3-5 năm với chất lượng cuộc sống ổn định.', 'Bệnh viện K Trung ương & Mayo Clinic — Tiên lượng và các yếu tố kéo dài thời gian sống ở bệnh nhân Glioma (https://benhvienk.vn)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bệnh nhân mắc Glioma Cấp độ 3 hoặc 4 (Glioblastoma) thì thời gian sống thêm và tiên lượng ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U tế bào hình sao (Astrocytoma) độ 2 ở người trẻ tuổi có chữa khỏi được không?', 'Astrocytoma độ 2 là u thần kinh đệm độ thấp tiến triển chậm, thường gặp ở người trẻ (20-40 tuổi). Nếu được phát hiện sớm và phẫu thuật cắt bỏ tối đa kết hợp xạ phẫu, bệnh nhân có thể kiểm soát bệnh ổn định, sống khỏe mạnh trên 10-15 năm hoặc lâu hơn mà không ảnh hưởng lớn đến tuổi thọ.', 'Tisch Brain Tumor Center - Duke University — Low-Grade Astrocytoma in Young Adults: Management and Outlook (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U tế bào hình sao (Astrocytoma) độ 2 ở người trẻ tuổi có chữa khỏi được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau điều trị u thần kinh đệm có thể quay lại làm việc và sinh hoạt bình thường không?', 'Nhiều người bệnh hồi phục rất tốt sau điều trị và có thể quay lại làm việc nhẹ nhàng, sinh hoạt gia đình bình thường. Điều quan trọng là tuân thủ phác đồ phục hồi chức năng vận động và ngôn ngữ, tránh căng thẳng thức khuya, tập thể dục nhẹ nhàng và uống thuốc chống động kinh dự phòng nếu bác sĩ chỉ định.', 'Tisch Brain Tumor Center - Duke University — Life After Brain Tumor Treatment: Rehabilitation and Quality of Life (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau điều trị u thần kinh đệm có thể quay lại làm việc và sinh hoạt bình thường không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bị u tuyến yên có con được không? Khối u này có gây vô sinh vĩnh viễn không?', 'U tuyến yên hoàn toàn không gây vô sinh vĩnh viễn. Khi nồng độ hormone prolactin tăng cao do khối u, nó sẽ tạm thời ức chế rụng trứng ở nữ và giảm số lượng tinh trùng ở nam. Sau khi được điều trị bằng thuốc hạ prolactin hoặc mổ bóc u, chu kỳ kinh nguyệt và chất lượng tinh trùng sẽ hồi phục, người bệnh hoàn toàn có thể mang thai và sinh con khỏe mạnh.', 'Cleveland Clinic — Pituitary Tumors and Fertility: Can You Get Pregnant? (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bị u tuyến yên có con được không? Khối u này có gây vô sinh vĩnh viễn không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'U tuyến yên có thể chữa khỏi bằng thuốc uống mà không cần mổ không?', 'Có! Đặc biệt với u tiết prolactin (Prolactinoma — dạng u tuyến yên phổ biến nhất), khoảng 80-90% trường hợp đáp ứng cực kỳ tốt với thuốc uống chủ vận Dopamine (như Cabergoline / Dostinex hoặc Bromocriptine). Thuốc làm khối u co nhỏ đáng kể hoặc biến mất hoàn toàn mà bệnh nhân không cần phải trải qua bất kỳ cuộc phẫu thuật nào.', 'Cleveland Clinic — Medical Management of Prolactinomas with Dopamine Agonists (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'U tuyến yên có thể chữa khỏi bằng thuốc uống mà không cần mổ không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau khi phẫu thuật mổ u tuyến yên giải ép, mắt bị mờ có sáng rõ lại được không?', 'Đa số bệnh nhân cảm nhận thị lực và tầm nhìn hai bên rìa mắt cải thiện rõ rệt chỉ vài ngày đến vài tuần sau mổ. Tuy nhiên, mức độ phục hồi phụ thuộc vào thời điểm can thiệp: nếu mổ sớm khi dây thần kinh thị giác chỉ bị chèn ép tạm thời thì mắt sẽ sáng lại gần như bình thường; nếu để quá muộn dẫn đến teo gai thị vĩnh viễn thì thị lực khó hồi phục trọn vẹn.', 'Cleveland Clinic — Visual Outcomes Following Pituitary Tumor Resection (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau khi phẫu thuật mổ u tuyến yên giải ép, mắt bị mờ có sáng rõ lại được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Mổ u tuyến yên nội soi qua mũi (xoang bướm) có đau nhiều không và bao lâu thì xuất viện?', 'Phẫu thuật nội soi qua đường mũi là kỹ thuật xâm lấn tối thiểu nên rất ít đau đớn, không để lại sẹo trên mặt hay đầu. Bệnh nhân chỉ có cảm giác nghẹt mũi nhẹ giống như bị cảm cúm trong vài ngày đầu. Thông thường sau mổ 3 đến 5 ngày, bệnh nhân đã có thể xuất viện về nhà và hồi phục sinh hoạt bình thường sau 2-3 tuần.', 'Cleveland Clinic & BV Việt Đức — Postoperative Care and Recovery for Transsphenoidal Surgery (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Mổ u tuyến yên nội soi qua mũi (xoang bướm) có đau nhiều không và bao lâu thì xuất viện?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau phẫu thuật u tuyến yên, người bệnh có phải uống thuốc bù hormone suốt đời không?', 'Điều này phụ thuộc vào lượng mô tuyến yên lành còn lại sau mổ. Nếu phần tuyến yên lành được bảo tồn tốt, người bệnh không cần dùng thuốc. Nếu phẫu thuật làm suy giảm một phần chức năng tuyến yên (suy tuyến yên), bác sĩ sẽ kê đơn viên uống bù hormone (như hormone tuyến giáp Levothyroxine, hydrocortisone) rất đơn giản, chi phí thấp và giúp người bệnh duy trì sức khỏe hoàn toàn bình thường.', 'Cleveland Clinic — Hormone Replacement Therapy After Pituitary Surgery (https://my.clevelandclinic.org/health/diseases/15328-pituitary-adenomas)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau phẫu thuật u tuyến yên, người bệnh có phải uống thuốc bù hormone suốt đời không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Kết quả AI báo ''No Tumor'' nhưng trong kết luận chụp MRI ghi có ''chấm thoái hóa chất trắng'' thì có nguy hiểm không?', 'Các nốt hoặc chấm tăng tín hiệu chất trắng (thường thấy ở người từ 40-50 tuổi trở lên) là tổn thương vi mạch máu não do lão hóa tự nhiên, tăng huyết áp nhẹ hoặc căng thẳng, hoàn toàn KHÔNG PHẢI là khối u não. Mô hình AI chẩn đoán ''No Tumor'' là chuẩn xác trong việc khẳng định bạn không có u tân sinh trong sọ.', 'Khuyến cáo chuyên môn dự án AI chẩn đoán MRI — Phân biệt thoái hóa chất trắng vi mạch với khối u não trên MRI (https://moh.gov.vn)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Kết quả AI báo ''No Tumor'' nhưng trong kết luận chụp MRI ghi có ''chấm thoái hóa chất trắng'' thì có nguy hiểm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nếu kết quả chụp MRI não bình thường, tôi có cần phải chụp lại định kỳ hàng năm không?', 'Người bình thường có kết quả MRI bình thường không cần thiết phải chụp lại hàng năm để tránh tốn kém chi phí y tế. Bạn chỉ cần đi khám và chụp lại khi xuất hiện các triệu chứng thần kinh mới như: đau đầu kéo dài tăng dần, cơn co giật, yếu liệt chi hoặc mắt mờ đột ngột.', 'Khuyến cáo chuyên môn dự án AI chẩn đoán MRI — Chỉ định chụp lại cộng hưởng từ sọ não trong theo dõi sức khỏe (https://moh.gov.vn)', 'tumor_classification'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nếu kết quả chụp MRI não bình thường, tôi có cần phải chụp lại định kỳ hàng năm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chụp cộng hưởng từ (MRI) sọ não là gì? Chụp MRI có bị nhiễm xạ tia X như chụp CT không?', 'Chụp cộng hưởng từ (MRI) sử dụng từ trường mạnh và sóng vô tuyến để tạo ra hình ảnh chi tiết của não bộ mà hoàn toàn KHÔNG sử dụng tia X, do đó người chụp không bị phơi nhiễm bức xạ ion hóa nguy hiểm. Đây là phương pháp chẩn đoán hình ảnh an toàn, có độ tương phản mô mềm tối ưu nhất để khảo sát các tổn thương và khối u trong sọ não.', 'Radiopaedia & Vinmec — Nguyên lý an toàn và ưu thế của chụp cộng hưởng từ MRI sọ não (https://www.vinmec.com)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chụp cộng hưởng từ (MRI) sọ não là gì? Chụp MRI có bị nhiễm xạ tia X như chụp CT không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao chụp MRI phát hiện u não phải tiêm thuốc đối quang từ (Gadolinium)? Có hại thận không?', 'Thuốc đối quang từ (chứa Gadolinium) được tiêm vào tĩnh mạch để làm sáng rõ hàng rào máu não bị tổn thương và mạch máu nuôi u, giúp phân định chính xác ranh giới, kích thước và bản chất khối u. Thuốc an toàn và đào thải qua thận trong 24 giờ; bệnh nhân sẽ được xét nghiệm chức năng thận (chỉ số eGFR/Creatinine) trước khi tiêm để đảm bảo an toàn tuyệt đối.', 'Mayo Clinic & BV Đa khoa Tâm Anh — Chỉ định và mức độ an toàn của thuốc đối quang từ trong chụp MRI não (https://tamanhhospital.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao chụp MRI phát hiện u não phải tiêm thuốc đối quang từ (Gadolinium)? Có hại thận không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Các chuỗi xung T1, T2 và FLAIR trên kết quả đọc MRI có ý nghĩa như thế nào?', 'T1, T2 và FLAIR là các chế độ quét cộng hưởng từ khác nhau: T1 cho thấy cấu trúc giải phẫu bình thường và ngấm thuốc của khối u; T2 hiển thị dịch não tủy và các vùng phù nề có màu sáng; Chuỗi xung FLAIR đặc biệt giúp xóa tín hiệu dịch não tủy tự do, làm nổi bật rõ ranh giới các tổn thương bệnh lý và vùng mô não bị phù xung quanh khối u.', 'Radiopaedia — MRI Brain Sequences: T1, T2, and FLAIR Explained (https://radiopaedia.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Các chuỗi xung T1, T2 và FLAIR trên kết quả đọc MRI có ý nghĩa như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thuật ngữ ''tăng tín hiệu'' (hyperintense) và ''giảm tín hiệu'' (hypointense) trong kết luận MRI nghĩa là gì?', '''Tăng tín hiệu'' có nghĩa là khu vực đó hiển thị sáng hơn bình thường trên ảnh (thường gặp ở vùng có dịch, phù não, chảy máu hoặc mỡ). ''Giảm tín hiệu'' có nghĩa là khu vực đó có màu tối hơn bình thường (như vôi hóa, dòng chảy mạch máu hoặc hoại tử). Bác sĩ kết hợp độ sáng tối trên nhiều xung để chẩn đoán thành phần bên trong khối u.', 'Radiopaedia — Understanding Signal Intensity on Magnetic Resonance Imaging (https://radiopaedia.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thuật ngữ ''tăng tín hiệu'' (hyperintense) và ''giảm tín hiệu'' (hypointense) trong kết luận MRI nghĩa là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thuật ngữ ''tổn thương ngấm thuốc dạng nhẫn / viền'' (ring-enhancing lesion) trên MRI cảnh báo điều gì?', 'Ngấm thuốc dạng nhẫn là hình ảnh khối u có phần viền ngoài bắt thuốc cản quang sáng rực, trong khi phần lõi trung tâm bị tối do hoại tử hoặc thoái hóa dịch. Dấu hiệu này thường gặp trong các khối u ác tính tiến triển nhanh như u nguyên bào thần kinh đệm (Glioblastoma), di căn não hoặc áp xe não, cần được bác sĩ chuyên khoa đánh giá ngay.', 'Mayo Clinic & Radiopaedia — Differential Diagnosis of Ring-Enhancing Brain Lesions (https://radiopaedia.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thuật ngữ ''tổn thương ngấm thuốc dạng nhẫn / viền'' (ring-enhancing lesion) trên MRI cảnh báo điều gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Dấu hiệu ''hiệu ứng choán chỗ'' (mass effect) và ''đè đẩy đường giữa'' trên MRI có nguy hiểm không?', 'Đây là dấu hiệu cảnh báo mức độ chèn ép nghiêm trọng. ''Hiệu ứng choán chỗ'' xuất hiện khi khối u và vùng phù não chiếm thể tích lớn làm xẹp các khe cuộn não và não thất. Nếu khối u đẩy lệch vách ngăn giữa hai bán cầu não (''đè đẩy đường giữa'' > 5mm), áp lực trong sọ tăng rất cao có nguy cơ gây tụt não, cần được xử trí y tế khẩn cấp.', 'Bệnh viện Hữu nghị Việt Đức — Đánh giá mức độ tăng áp lực nội sọ và đè đẩy đường giữa trên chẩn đoán hình ảnh (https://benhvienvietduc.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Dấu hiệu ''hiệu ứng choán chỗ'' (mass effect) và ''đè đẩy đường giữa'' trên MRI có nguy hiểm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Vùng ''phù não quanh u'' (peritumoral edema) trên MRI có phải là tế bào ung thư lan rộng không?', 'Phần lớn vùng phù não quanh u là chất lỏng (nước) ứ đọng trong các khoang gian bào do khối u chèn ép mạch máu hoặc tiết ra các chất gây tăng tính thấm thành mạch (như VEGF). Vùng phù này không hoàn toàn là tế bào khối u và có thể giảm đi nhanh chóng khi bệnh nhân được bác sĩ điều trị bằng thuốc chống phù não (corticoid/dexamethasone).', 'Radiopaedia & Bệnh viện K — Cơ chế và điều trị phù não quanh khối u thần kinh (https://benhvienk.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Vùng ''phù não quanh u'' (peritumoral edema) trên MRI có phải là tế bào ung thư lan rộng không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khối u có ''ranh giới rõ'' khác gì với khối u có ''ranh giới không rõ / thâm nhiễm'' trên phim MRI?', 'Khối u ''ranh giới rõ'' (như u màng não, u tuyến yên) có đường viền phân tách mạch lạc với mô não lành, giúp việc phẫu thuật bóc tách an toàn và triệt để hơn. Ngược lại, khối u ''ranh giới không rõ/thâm nhiễm'' (như u thần kinh đệm Glioma) có các tế bào u hòa lẫn vào mô não xung quanh, khiến việc xác định bờ ranh giới cắt bỏ hoàn toàn trở nên rất phức tạp.', 'Bệnh viện Hữu nghị Việt Đức & Johns Hopkins — Ý nghĩa tiên lượng của bờ ranh giới khối u trên ảnh cộng hưởng từ (https://benhvienvietduc.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khối u có ''ranh giới rõ'' khác gì với khối u có ''ranh giới không rõ / thâm nhiễm'' trên phim MRI?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Báo cáo MRI ghi khối u có ''vùng hoại tử trung tâm'' (central necrosis) phản ánh điều gì?', 'Vùng hoại tử trung tâm xảy ra khi khối u phát triển quá nhanh vượt quá khả năng cấp máu của hệ thống mạch nuôi, khiến các tế bào ở trung tâm khối u bị thiếu oxy và chết đi tạo thành ổ hoại tử thoái hóa dịch. Đây là một trong những đặc trưng hình ảnh quan trọng giúp phân biệt u ác tính cấp độ cao (như Glioblastoma) với u lành tính.', 'Radiopaedia — Central Necrosis in High-Grade Glial Tumors (https://radiopaedia.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Báo cáo MRI ghi khối u có ''vùng hoại tử trung tâm'' (central necrosis) phản ánh điều gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chụp cộng hưởng từ phổ (MRS) và chụp bó sợi thần kinh (DTI) là gì, khi nào cần làm thêm?', 'MRS là kỹ thuật đo nồng độ các chất hóa sinh (như Choline, Creatine, NAA) trong khối u để phân biệt u não với tổn thương viêm/nhiễm trùng; DTI là kỹ thuật dựng hình đường đi của các bó sợi thần kinh vận động và thị giác. Bác sĩ thường chỉ định làm thêm hai kỹ thuật cao cấp này trước khi phẫu thuật để vẽ bản đồ đường mổ tránh làm tổn thương các bó thần kinh sinh mệnh.', 'Bệnh viện Bạch Mai & Vinmec — Ứng dụng của MRI phổ (MRS) và chụp sức căng khuếch tán (DTI) trong phẫu thuật thần kinh (https://bachmai.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chụp cộng hưởng từ phổ (MRS) và chụp bó sợi thần kinh (DTI) là gì, khi nào cần làm thêm?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Mô hình AI trong hệ thống phân loại ảnh MRI thành 4 nhóm nào và hoạt động ra sao?', 'Hệ thống NeuroScan AI hiện vận hành mô hình học sâu chuẩn ONNX (brain_mri_student.onnx) suy luận trực tiếp trên nền tảng Web (ONNX Runtime Web) và Python FastAPI để phân loại ảnh MRI vào 1 trong 4 nhóm: (1) Glioma (U tế bào thần kinh đệm); (2) Meningioma (U màng não); (3) Pituitary (U tuyến yên); và (4) No Tumor (Không phát hiện u). Song song đó, nhóm phát triển đang nghiên cứu mở rộng kiến trúc Hybrid Multi-Backbone Ensemble (ConvNeXt, Swin Transformer V2, EfficientNetV2) cho các phiên bản tiếp theo.', 'Tài liệu kỹ thuật hệ thống AI y tế dự án — Kiến trúc mô hình Ensemble phân loại đa lớp ảnh MRI sọ não (https://neuroscan.pages.dev/model-overview)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Mô hình AI trong hệ thống phân loại ảnh MRI thành 4 nhóm nào và hoạt động ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chỉ số độ tin cậy (Confidence / Xác suất %) mà mô hình AI trả về có ý nghĩa chính xác là gì?', 'Chỉ số xác suất (ví dụ: 88% hay 95%) thể hiện mức độ tương quan toán học giữa các đặc trưng trên ảnh MRI bạn tải lên với các mẫu bệnh phẩm cùng loại mà AI đã được học trong tập huấn luyện. Chỉ số này phản ánh độ chắc chắn về mặt nhận diện hình ảnh của thuật toán, KHÔNG phản ánh kích thước, giai đoạn hay mức độ nặng/nhẹ lâm sàng của bệnh.', 'Tài liệu kỹ thuật hệ thống AI y tế dự án — Diễn giải ý nghĩa xác suất đầu ra của mạng nơ-ron phân loại ảnh y khoa (https://neuroscan.pages.dev/model-overview)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chỉ số độ tin cậy (Confidence / Xác suất %) mà mô hình AI trả về có ý nghĩa chính xác là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Kết quả AI dự đoán ''Glioma 94%'' có đồng nghĩa với việc tôi có 94% khả năng bị ung thư ác tính không?', 'Hoàn toàn không! Con số 94% chỉ có nghĩa là: ''Thuật toán nhận thấy bức ảnh này mang 94% đặc điểm giống với hình ảnh Glioma''. Trong thực tế, Glioma có cả cấp độ thấp (lành tính tiến triển chậm) và cấp độ cao (ác tính). Con số phần trăm của AI không phải là tỷ lệ ác tính và cũng không phải cơ hội sống của bạn; chỉ có bác sĩ kết hợp sinh thiết mới xác định được chính xác bản chất khối u.', 'Khuyến cáo an toàn hệ thống AI chẩn đoán hình ảnh — Tránh hiểu lầm giữa xác suất mô hình hình ảnh và tỷ lệ ác tính bệnh học (https://moh.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Kết quả AI dự đoán ''Glioma 94%'' có đồng nghĩa với việc tôi có 94% khả năng bị ung thư ác tính không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nếu mô hình AI trả về kết quả phân vân giữa 2 loại u (ví dụ: Glioma 51% và Meningioma 47%) thì hiểu thế nào?', 'Khi xác suất giữa hai nhãn xấp xỉ nhau, điều đó cho thấy lát cắt ảnh MRI này mang các đặc trưng hình thái trung gian mà mô hình nhận diện chưa rõ ràng (ví dụ khối u nằm sát ranh giới màng não hoặc hình ảnh bị mờ). Trong trường hợp này, kết quả chỉ mang tính tham khảo và người bệnh bắt buộc cần bác sĩ chẩn đoán hình ảnh đọc trực tiếp toàn bộ chuỗi xung chụp gốc.', 'Tài liệu kỹ thuật hệ thống AI y tế dự án — Xử lý các ca dự đoán ranh giới xác suất không đồng nhất trong AI y khoa (https://neuroscan.pages.dev/model-overview)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nếu mô hình AI trả về kết quả phân vân giữa 2 loại u (ví dụ: Glioma 51% và Meningioma 47%) thì hiểu thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao hệ thống AI yêu cầu ảnh chụp MRI tải lên phải đúng lát cắt giải phẫu (Axial/Coronal) và đủ rõ nét?', 'Mô hình thị giác máy tính được huấn luyện chuẩn hóa trên các lát cắt MRI sọ não tiêu chuẩn (chủ yếu mặt cắt ngang Axial cho nhu mô/màng não và mặt cắt đứng ngang Coronal cho vùng hố yên/tuyến yên) vì các mặt phẳng này hiển thị rõ cấu trúc đối xứng hai bán cầu não và vùng tổn thương. Nếu người dùng tải lên ảnh mờ, ảnh chụp lại màn hình bị lóa, nghiêng lệch hoặc dính chữ/thước đo che vùng não, độ chính xác của AI sẽ bị suy giảm đáng kể.', 'Hướng dẫn sử dụng hệ thống web AI chẩn đoán MRI — Quy chuẩn chất lượng và định dạng ảnh MRI đầu vào cho mô hình (https://neuroscan.pages.dev/model-overview)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao hệ thống AI yêu cầu ảnh chụp MRI tải lên phải đúng lát cắt giải phẫu (Axial/Coronal) và đủ rõ nét?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Những giới hạn kỹ thuật lớn nhất của mô hình AI hỗ trợ chẩn đoán ảnh MRI là gì?', 'Hệ thống AI có 3 giới hạn cốt lõi: (1) AI chỉ quan sát một lát cắt 2D đơn lẻ mà không có cái nhìn 3D đa chuỗi xung như bác sĩ; (2) AI không có thông tin lâm sàng của bệnh nhân (tuổi tác, tiền sử bệnh, triệu chứng đau đầu hay sốt); và (3) AI chỉ được huấn luyện trên 4 nhóm bệnh chính nên không nhận diện được các dạng u hiếm gặp khác (như u nguyên bào tủy, u sọ hầu, u dây thần kinh).', 'Khuyến cáo an toàn hệ thống AI chẩn đoán hình ảnh — Nhận biết các giới hạn kỹ thuật của hệ thống AI trong thực hành y tế (https://moh.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Những giới hạn kỹ thuật lớn nhất của mô hình AI hỗ trợ chẩn đoán ảnh MRI là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao kết luận dự đoán của AI không thể thay thế cho sinh thiết giải phẫu bệnh?', 'Hình ảnh MRI và dự đoán của AI chỉ thể hiện hình thái vĩ mô bên ngoài của tổn thương. Trong khi đó, sinh thiết giải phẫu bệnh kiểm tra trực tiếp tế bào dưới kính hiển vi và xét nghiệm đột biến gen phân tử (tiêu chuẩn vàng duy nhất). Hai khối u có hình ảnh MRI tương đối giống nhau nhưng bản chất sinh học và phác đồ điều trị có thể hoàn toàn trái ngược nhau.', 'Bộ Y tế Việt Nam — Nguyên tắc chẩn đoán mô bệnh học trong phân loại ung bướu thần kinh (https://moh.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao kết luận dự đoán của AI không thể thay thế cho sinh thiết giải phẫu bệnh?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Có những bệnh lý nào không phải u nhưng có thể khiến AI nhận diện nhầm thành u não (dương tính giả)?', 'Một số bệnh lý nội sọ lành tính có thể tạo ra hình ảnh bắt thuốc và phù nề tương tự u não khiến AI nhận diện nhầm: (1) Ổ áp xe não do vi khuẩn; (2) Ổ nhồi máu não bán cấp; (3) Khối dị dạng mạch máu não (AVM hoặc u mạch thể hang); và (4) Mảng xơ cứng rải rác (Multiple Sclerosis). Bác sĩ sẽ dựa vào xét nghiệm máu, nhiệt độ cơ thể và diễn biến triệu chứng để phân biệt chính xác.', 'Radiopaedia & Mayo Clinic — Non-neoplastic Brain Lesions that Mimic Brain Tumors on MRI (https://radiopaedia.org)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Có những bệnh lý nào không phải u nhưng có thể khiến AI nhận diện nhầm thành u não (dương tính giả)?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khi nào hệ thống AI dự đoán ''No Tumor'' nhưng người bệnh vẫn BẮT BUỘC phải đi khám bác sĩ ngay?', 'Người bệnh vẫn phải đi khám bác sĩ ngay lập tức nếu xuất hiện các ''dấu hiệu cờ đỏ'': Cơn co giật lần đầu, đau đầu dữ dội tăng dần kèm nôn vọt vào sáng sớm, yếu liệt tay chân hoặc mất ý thức thoáng qua. Khối u có thể nằm ở lát cắt khác mà ảnh tải lên chưa quét tới, hoặc triệu chứng do phình động mạch não, viêm màng não gây ra mà một bức ảnh 2D không thể bao quát hết.', 'Bệnh viện Bạch Mai & Mayo Clinic — Cảnh báo an toàn lâm sàng khi kết quả chẩn đoán hình ảnh âm tính (https://bachmai.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khi nào hệ thống AI dự đoán ''No Tumor'' nhưng người bệnh vẫn BẮT BUỘC phải đi khám bác sĩ ngay?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Vai trò thực sự và giá trị pháp lý của hệ thống AI chẩn đoán u não này là gì?', 'Hệ thống AI này là một công cụ hỗ trợ sàng lọc sơ bộ và trợ lý cung cấp thông tin y tế tham khảo trong khuôn khổ đề tài công nghệ đám mây. Hệ thống hoàn toàn KHÔNG CÓ giá trị pháp lý thay thế cho kết luận chẩn đoán, toa thuốc hay y lệnh của bác sĩ chuyên khoa y tế. Bệnh nhân luôn phải mang kết quả phim chụp đến cơ sở y tế chuyên môn để được thăm khám và điều trị.', 'Khuyến cáo an toàn và tuyên bố từ chối trách nhiệm hệ thống y tế số — Tuyên bố miễn trừ trách nhiệm y khoa và hướng dẫn sử dụng AI an toàn (https://moh.gov.vn)', 'mri_ai_explanation'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Vai trò thực sự và giá trị pháp lý của hệ thống AI chẩn đoán u não này là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Các phương pháp điều trị chính cho bệnh u não hiện nay bao gồm những gì?', 'Theo tài liệu từ Duke University và Bệnh viện Đa khoa Tâm Anh, điều trị u não là sự phối hợp đa mô thức tùy thuộc vào vị trí, kích thước và cấp độ của u: (1) Phẫu thuật cắt bỏ tối đa khối u an toàn (phương pháp đầu tay); (2) Xạ trị vào giường u; (3) Hóa trị (tiêu biểu bằng thuốc Temozolomide); và (4) Liệu pháp nhắm trúng đích, xạ phẫu định vị hoặc chăm sóc giảm nhẹ.', 'Tisch Brain Tumor Center - Duke University & BV Đa khoa Tâm Anh — Chẩn đoán và các phương pháp điều trị u não hiện đại (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Các phương pháp điều trị chính cho bệnh u não hiện nay bao gồm những gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phẫu thuật mở nắp sọ (Craniotomy) là gì? Khái niệm ''cắt bỏ tối đa an toàn'' có nghĩa là sao?', 'Theo hướng dẫn từ Duke University và Vinmec, ''cắt bỏ tối đa an toàn'' (Maximal Safe Resection) có nghĩa là phẫu thuật viên mở một cửa sổ xương sọ để lấy đi càng nhiều mô khối u càng tốt, nhưng phải tuyệt đối bảo tồn các vùng não chức năng quan trọng (vận động, phát âm, thị giác) để tránh nguy cơ để lại di chứng tàn tật sau mổ.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Nguyên tắc phẫu thuật cắt bỏ tối đa an toàn trong điều trị u não (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phẫu thuật mở nắp sọ (Craniotomy) là gì? Khái niệm ''cắt bỏ tối đa an toàn'' có nghĩa là sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hệ thống định vị 3D Navigation và theo dõi điện sinh lý thần kinh trong mổ giúp ích gì cho người bệnh?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, hệ thống Navigation hoạt động như ''GPS dẫn đường trong sọ não'', giúp bác sĩ định vị ranh giới khối u với độ chính xác dưới 1mm. Thiết bị theo dõi điện sinh lý liên tục cảnh báo nếu dụng cụ mổ tiến sát các bó sợi thần kinh vận động, giúp giảm thiểu tối đa nguy cơ liệt chi cho bệnh nhân.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Ứng dụng Navigation và công nghệ hiện đại trong phẫu thuật u não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hệ thống định vị 3D Navigation và theo dõi điện sinh lý thần kinh trong mổ giúp ích gì cho người bệnh?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Xạ trị u não là gì và một liệu trình thường kéo dài trong bao lâu?', 'Theo tài liệu từ Duke University và Vinmec, xạ trị sử dụng chùm tia bức xạ photon năng lượng cao chiếu trực tiếp vào giường u để phá hủy cấu trúc DNA của các tế bào u còn sót lại. Một liệu trình xạ trị chuẩn thường kéo dài 5 đến 6 tuần (bệnh nhân đến chiếu xạ từ thứ Hai đến thứ Sáu, mỗi lần chiếu chỉ mất khoảng 10-15 phút và nghỉ hai ngày cuối tuần).', 'Tisch Brain Tumor Center - Duke University & Vinmec — Quy trình xạ trị và liệu trình điều trị u thần kinh trung ương (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Xạ trị u não là gì và một liệu trình thường kéo dài trong bao lâu?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Xạ trị u não có bị rụng tóc toàn bộ đầu không và các tác dụng phụ thường gặp là gì?', 'Theo Mayo Clinic và Vinmec, xạ trị u não chỉ gây rụng tóc cục bộ tại đúng vùng da đầu mà chùm tia bức xạ đi qua, tóc thường mọc lại sau 3-6 tháng kết thúc điều trị. Các tác dụng phụ phổ biến khác gồm: mệt mỏi, da đầu ửng đỏ nhẹ như rám nắng và cảm giác nặng đầu thoáng qua do phù nề mô não (được kiểm soát tốt bằng thuốc chống phù não).', 'Mayo Clinic & Vinmec — Quản lý tác dụng phụ của xạ trị não và chăm sóc người bệnh (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Xạ trị u não có bị rụng tóc toàn bộ đầu không và các tác dụng phụ thường gặp là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Xạ phẫu Dao Gamma (Gamma Knife) khác gì xạ trị thông thường? Trường hợp nào được chỉ định?', 'Theo Johns Hopkins Medicine và Tâm Anh, Dao Gamma thực chất là phương pháp xạ phẫu không cần mở hộp sọ, hội tụ hàng trăm chùm tia liều cao chính xác vào khối u chỉ trong 1 lần điều trị duy nhất mà không cần gây mê. Phương pháp này chỉ định hiệu quả cho khối u nhỏ (dưới 3cm), ranh giới rõ ràng như u màng não nền sọ khó mổ, u tuyến yên tồn dư hoặc ổ di căn não đơn độc.', 'Johns Hopkins Medicine - Meningioma Center & BV Tâm Anh — Chỉ định và ưu điểm của xạ phẫu Gamma Knife trong điều trị u nội sọ (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Xạ phẫu Dao Gamma (Gamma Knife) khác gì xạ trị thông thường? Trường hợp nào được chỉ định?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thuốc hóa trị Temozolomide (Temodar) dạng viên uống hoạt động thế nào trong điều trị u thần kinh đệm?', 'Theo Duke University và Mayo Clinic, Temozolomide là thuốc hóa trị đường uống có đặc tính đặc biệt là vượt qua được hàng rào máu não. Thuốc gắn các nhóm alkyl vào DNA tế bào u gây đứt gãy gen, khiến tế bào u ngừng phân chia và tự chết, đặc biệt có đáp ứng rất tốt ở những bệnh nhân có gen MGMT bị methyl hóa.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Cơ chế tác dụng của Temozolomide trong điều trị u thần kinh đệm (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thuốc hóa trị Temozolomide (Temodar) dạng viên uống hoạt động thế nào trong điều trị u thần kinh đệm?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phác đồ Stupp kết hợp đồng thời hóa - xạ trị cho bệnh nhân Glioma cấp độ cao là gì?', 'Theo Duke University, phác đồ Stupp là tiêu chuẩn điều trị quốc tế cho Glioblastoma: Bệnh nhân uống Temozolomide hàng ngày kết hợp đồng thời với xạ trị trong 6 tuần; sau đó nghỉ 4 tuần và chuyển sang giai đoạn hóa trị duy trì (uống Temozolomide 5 ngày mỗi chu kỳ 28 ngày, lặp lại trong 6 chu kỳ) giúp kéo dài đáng kể thời gian sống thêm.', 'Tisch Brain Tumor Center - Duke University — Phác đồ Stupp trong điều trị Glioblastoma và u thần kinh đệm cấp độ cao (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phác đồ Stupp kết hợp đồng thời hóa - xạ trị cho bệnh nhân Glioma cấp độ cao là gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thuốc nhắm trúng đích Bevacizumab (Avastin) được sử dụng khi nào trong điều trị u não?', 'Theo Duke University và Mayo Clinic, Bevacizumab là kháng thể đơn dòng ức chế yếu tố tăng sinh mạch máu VEGF. Thuốc được chỉ định khi khối u thần kinh đệm tái phát hoặc khi vùng phù não quanh u quá nặng nề kháng trị với corticoid. Thuốc giúp cắt đứt nguồn máu nuôi u và làm giảm nhanh hiện tượng phù não, cải thiện rõ rệt chất lượng sống cho bệnh nhân.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Liệu pháp nhắm trúng đích Bevacizumab trong u thần kinh đệm tái phát (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thuốc nhắm trúng đích Bevacizumab (Avastin) được sử dụng khi nào trong điều trị u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao bệnh nhân u não BẮT BUỘC phải uống thuốc chống động kinh đều đặn và không được tự ý bỏ thuốc?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, thuốc chống động kinh (như Levetiracetam) giúp ổn định điện thế màng tế bào vỏ não bị khối u kích thích. Nếu tự ý ngưng thuốc đột ngột hoặc quên liều, ngưỡng co giật sẽ tụt dốc, dễ kích hoạt cơn động kinh dữ dội liên tục (trạng thái động kinh) đe dọa trực tiếp tính mạng hoặc gây thiếu oxy não.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Hướng dẫn tuân thủ điều trị thuốc chống động kinh ở bệnh nhân u não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao bệnh nhân u não BẮT BUỘC phải uống thuốc chống động kinh đều đặn và không được tự ý bỏ thuốc?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thuốc Dexamethasone (corticoid) giảm phù não dùng thế nào và tại sao phải giảm liều từ từ?', 'Theo Mayo Clinic và Vinmec, Dexamethasone là thuốc kháng viêm mạnh giúp rút bớt dịch phù nề trong sọ não. Khi dùng kéo dài, tuyến thượng thận sẽ tạm ngừng sản xuất hormone tự nhiên. Do đó, người bệnh bắt buộc phải giảm liều từ từ theo từng nấc do bác sĩ hướng dẫn; tuyệt đối KHÔNG ngưng đột ngột để tránh suy tuyến thượng thận cấp nguy kịch.', 'Mayo Clinic & Vinmec — Nguyên tắc sử dụng và giảm liều Corticoid trong phù não (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thuốc Dexamethasone (corticoid) giảm phù não dùng thế nào và tại sao phải giảm liều từ từ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Lịch trình chụp MRI tái khám định kỳ sau khi điều trị u não thường diễn ra như thế nào?', 'Theo Johns Hopkins và Vinmec, bệnh nhân sẽ chụp MRI sớm trong vòng 24 - 72 giờ đầu sau mổ để đánh giá mức độ cắt bỏ u. Trong 1-2 năm đầu, với u ác tính (Glioma độ cao), bệnh nhân cần chụp MRI mỗi 2 - 3 tháng một lần; với u lành tính (u màng não, u tuyến yên), lịch chụp tái khám thường giãn cách mỗi 6 tháng đến 1 năm một lần.', 'Johns Hopkins Medicine & Vinmec — Quy chuẩn theo dõi chẩn đoán hình ảnh MRI sau điều trị khối u não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Lịch trình chụp MRI tái khám định kỳ sau khi điều trị u não thường diễn ra như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau mổ u não bị yếu liệt tay chân thì tập phục hồi chức năng vận động ra sao?', 'Theo Bệnh viện Đa khoa Tâm Anh, tập phục hồi chức năng nên bắt đầu càng sớm càng tốt (thường từ ngày thứ 2-3 sau mổ tại giường bệnh): Bắt đầu từ lăn trở, ngồi dậy, tập co duỗi khớp thụ động để chống teo cơ; sau đó phối hợp kỹ thuật viên tập thăng bằng đứng, tập đi với khung để kích thích não bộ tái lập đường truyền thần kinh mới.', 'Bệnh viện Đa khoa Tâm Anh — Phục hồi chức năng vận động cho bệnh nhân sau phẫu thuật u não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau mổ u não bị yếu liệt tay chân thì tập phục hồi chức năng vận động ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau phẫu thuật bị nói ngọng, nói khó hoặc khó hiểu ngôn ngữ thì phục hồi âm ngữ trị liệu thế nào?', 'Theo Vinmec và Bệnh viện Đa khoa Tâm Anh, âm ngữ trị liệu giúp phục hồi vùng ngôn ngữ: Tập cơ miệng, môi, lưỡi để phát âm chuẩn nguyên âm; tập gọi tên đồ vật qua tranh ảnh trực quan; tập đọc to câu ngắn và gia đình cần kiên nhẫn trò chuyện hàng ngày bằng câu đơn giản, không ngắt lời hay nói hộ người bệnh.', 'Bệnh viện Đa khoa Quốc tế Vinmec & BV Tâm Anh — Phục hồi chức năng giao tiếp và ngôn ngữ cho bệnh nhân tổn thương não (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau phẫu thuật bị nói ngọng, nói khó hoặc khó hiểu ngôn ngữ thì phục hồi âm ngữ trị liệu thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hướng dẫn chăm sóc vết mổ sọ não tại nhà và những dấu hiệu nhiễm trùng cần nhập viện ngay?', 'Theo Johns Hopkins và Vinmec, luôn giữ vết mổ khô ráo, sạch sẽ, không tự ý bôi thuốc lá đắp cao. Đưa bệnh nhân đến bệnh viện ngay nếu có dấu hiệu nhiễm trùng hoặc rò dịch não tủy: Vết mổ sưng đỏ, căng phồng, rỉ dịch trong suốt hoặc mủ vàng; đau đầu tăng dữ dội, sốt cao trên 38.5 độ C hoặc cứng cổ gáy.', 'Johns Hopkins Medicine & Vinmec — Hướng dẫn chăm sóc vết mổ và nhận biết biến chứng sau mổ não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hướng dẫn chăm sóc vết mổ sọ não tại nhà và những dấu hiệu nhiễm trùng cần nhập viện ngay?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chế độ dinh dưỡng cho người sau phẫu thuật và trong giai đoạn hóa - xạ trị u não cần lưu ý gì?', 'Theo Vinmec và Mayo Clinic, người bệnh cần ăn chế độ giàu đạm (thịt nạc, cá, trứng) để mau lành vết mổ; tăng cường rau xanh, trái cây nhiều chất xơ để CHỐNG TÁO BÓN (vì động tác rặn khi táo bón làm tăng vọt áp lực nội sọ rất nguy hiểm); uống đủ 1.5 - 2 lít nước mỗi ngày; giảm ăn mặn nếu dùng corticoid và kiêng rượu bia.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Mayo Clinic — Chế độ dinh dưỡng tối ưu cho bệnh nhân phẫu thuật thần kinh (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chế độ dinh dưỡng cho người sau phẫu thuật và trong giai đoạn hóa - xạ trị u não cần lưu ý gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh u não có nên uống các loại thuốc nam, thuốc bắc truyền miệng để ''tiêu u'' không?', 'Theo cảnh báo từ Vinmec và Đông y Sơn Hà, không có bất kỳ bài thuốc nam hay thảo dược truyền miệng nào có bằng chứng khoa học chứng minh khả năng tiêu diệt khối u não. Nhiều loại thuốc sắc không rõ nguồn gốc còn chứa độc chất gây suy gan, suy thận và tương tác làm mất tác dụng thuốc chống động kinh, làm lỡ mất thời gian vàng điều trị.', 'Vinmec & Đông y Sơn Hà — Cảnh báo tác hại của việc tự ý dùng thuốc nam không rõ nguồn gốc trong điều trị khối u (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh u não có nên uống các loại thuốc nam, thuốc bắc truyền miệng để ''tiêu u'' không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Những câu hỏi quan trọng nhất người bệnh và gia đình nên chuẩn bị để hỏi bác sĩ phẫu thuật trước khi mổ?', 'Theo khuyến cáo từ Johns Hopkins và Vinmec, người bệnh nên hỏi: (1) Mục tiêu cuộc mổ là cắt bỏ trọn vẹn khối u hay chỉ sinh thiết/giải ép?; (2) Khối u nằm gần vùng chức năng nào và rủi ro lớn nhất sau mổ là gì?; (3) Bác sĩ có sử dụng định vị vi phẫu Navigation 3D không?; (4) Thời gian nằm viện dự kiến bao lâu?; và (5) Sau mổ có cần xạ/hóa trị tiếp không?', 'Johns Hopkins Medicine & Vinmec — Checklist câu hỏi dành cho người bệnh trước phẫu thuật sọ não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Những câu hỏi quan trọng nhất người bệnh và gia đình nên chuẩn bị để hỏi bác sĩ phẫu thuật trước khi mổ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Những câu hỏi người bệnh nên trao đổi với bác sĩ ung bướu trước khi bắt đầu xạ trị hoặc hóa trị?', 'Theo Duke University và Vinmec, nên hỏi: (1) Mục đích của xạ/hóa trị là triệt căn hay kéo dài thời gian sống?; (2) Phác đồ thuốc Temozolomide cụ thể là gì và liệu trình kéo dài bao nhiêu tuần?; (3) Tác dụng phụ nào thường gặp và chuẩn bị thuốc chống nôn ra sao?; (4) Cần kiêng cữ những gì trong sinh hoạt?; và (5) Dấu hiệu nào cần liên hệ khẩn cấp với bác sĩ?', 'Tisch Brain Tumor Center - Duke University & Vinmec — Hướng dẫn người bệnh trao đổi về phác đồ điều trị ung bướu thần kinh (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Những câu hỏi người bệnh nên trao đổi với bác sĩ ung bướu trước khi bắt đầu xạ trị hoặc hóa trị?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao chatbot AI tuyệt đối KHÔNG ĐƯỢC tự cá nhân hóa phác đồ điều trị hoặc hướng dẫn thay đổi liều thuốc?', 'Mỗi bệnh nhân u não có thể trạng, độ tuổi, chức năng gan thận và đột biến phân tử (IDH, 1p/19q) hoàn toàn khác nhau. Việc kê đơn, chỉnh liều thuốc thần kinh (như corticoid chống phù não hay thuốc chống co giật) bắt buộc phải do bác sĩ chuyên khoa theo dõi lâm sàng trực tiếp. Chatbot AI chỉ cung cấp thông tin giáo dục y tế đại cương, không có quyền thay thế y lệnh bác sĩ.', 'Khuyến cáo an toàn AI y tế & Bệnh viện Đa khoa Tâm Anh — Quy chuẩn an toàn và giới hạn trách nhiệm của trí tuệ nhân tạo trong y tế (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao chatbot AI tuyệt đối KHÔNG ĐƯỢC tự cá nhân hóa phác đồ điều trị hoặc hướng dẫn thay đổi liều thuốc?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau phẫu thuật mổ u não bao lâu thì người bệnh được gội đầu và tắm rửa bình thường?', 'Theo Vinmec và Johns Hopkins, người bệnh chỉ được gội đầu sau khi đã cắt chỉ vết mổ (thường từ 7 đến 10 ngày sau mổ) và vết mổ đã khô hoàn toàn, không rỉ dịch. Trong thời gian chưa cắt chỉ, chỉ nên lau người bằng nước ấm, tuyệt đối không để nước dính vào băng hoặc vết rạch da đầu để tránh vi khuẩn xâm nhập gây viêm màng não.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Johns Hopkins — Hướng dẫn vệ sinh cá nhân và gội đầu an toàn sau phẫu thuật sọ não (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau phẫu thuật mổ u não bao lâu thì người bệnh được gội đầu và tắm rửa bình thường?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ u não có được đi máy bay không? Cần lưu ý gì về áp suất khoang máy bay?', 'Theo Mayo Clinic và Bệnh viện Đa khoa Tâm Anh, người bệnh KHÔNG NÊN đi máy bay trong ít nhất 4 đến 6 tuần đầu sau mổ mở sọ. Sau mổ, thường còn một lượng nhỏ không khí tồn đọng trong hộp sọ (khí nội sọ); sự thay đổi áp suất khi bay có thể làm khí này giãn nở gây đau đầu dữ dội, tăng áp lực nội sọ hoặc tụt não. Cần được bác sĩ chụp phim kiểm tra đồng ý trước khi bay.', 'Mayo Clinic & Bệnh viện Đa khoa Tâm Anh — An toàn bay và hạn chế di chuyển hàng không sau phẫu thuật thần kinh (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ u não có được đi máy bay không? Cần lưu ý gì về áp suất khoang máy bay?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Đang uống thuốc chống động kinh sau mổ u não thì có được tự lái xe máy hoặc ô tô không?', 'Theo hướng dẫn an toàn thần kinh từ Mayo Clinic và Tâm Anh, người bệnh tuyệt đối KHÔNG ĐƯỢC tự lái xe trong ít nhất 6 đến 12 tháng kể từ cơn co giật cuối cùng hoặc sau phẫu thuật sọ não. Một cơn động kinh bất ngờ dù chỉ kéo dài vài giây khi đang lái xe cũng có thể gây tai nạn nguy hiểm tính mạng cho bản thân và người khác.', 'Mayo Clinic & Bệnh viện Đa khoa Tâm Anh — Khuyến cáo an toàn lái xe ở bệnh nhân có tiền sử tổn thương não và co giật (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Đang uống thuốc chống động kinh sau mổ u não thì có được tự lái xe máy hoặc ô tô không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Vùng da đầu xung quanh vết mổ bị tê bì mất cảm giác hoặc thỉnh thoảng giật nhói có nguy hiểm không?', 'Theo Johns Hopkins và Vinmec, đây là hiện tượng bình thường và phổ biến. Khi rạch da đầu mở nắp sọ, các nhánh thần kinh cảm giác ngoại biên li ti bị cắt đứt tạm thời, gây cảm giác tê bì, mất cảm giác như ''đội mũ dạ'' hoặc châm chích kiến bò. Cảm giác này sẽ hồi phục dần trong 6 đến 12 tháng khi các đầu dây thần kinh tái sinh.', 'Johns Hopkins Medicine & Vinmec — Hiện tượng dị cảm và hồi phục thần kinh da đầu sau mổ sọ não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Vùng da đầu xung quanh vết mổ bị tê bì mất cảm giác hoặc thỉnh thoảng giật nhói có nguy hiểm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Trước khi phẫu thuật u não có bắt buộc phải cạo trọc toàn bộ đầu không? Sau mổ tóc có mọc lại che sẹo được không?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, phẫu thuật viên hiện nay thường chỉ cạo một dải tóc hẹp khoảng 1-2 cm dọc theo đường rạch mổ dự kiến chứ không bắt buộc cạo trọc cả đầu, giúp bảo toàn tính thẩm mỹ. Tóc xung quanh sẽ mọc lại bình thường sau vài tuần và hoàn toàn có thể phủ kín che đi đường sẹo mổ.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Chăm sóc và bảo tồn tóc trong phẫu thuật thần kinh hiện đại (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Trước khi phẫu thuật u não có bắt buộc phải cạo trọc toàn bộ đầu không? Sau mổ tóc có mọc lại che sẹo được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Mảnh xương sọ mở ra trong lúc phẫu thuật sau này có liền lại chắc chắn như cũ không?', 'Theo Johns Hopkins và Vinmec, sau khi bóc u xong, mảnh xương sọ sẽ được đặt lại vị trí cũ và cố định chắc chắn bằng nẹp và vít nhỏ bằng hợp kim Titan (không gỉ sét, tương thích sinh học cao và an toàn khi chụp MRI sau này). Theo thời gian, tế bào xương sẽ tự liền xương sinh học, đảm bảo hộp sọ bảo vệ não vững chắc như ban đầu.', 'Johns Hopkins Medicine & Vinmec — Kỹ thuật cố định nắp sọ bằng nẹp vi thể Titan trong phẫu thuật não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Mảnh xương sọ mở ra trong lúc phẫu thuật sau này có liền lại chắc chắn như cũ không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau mổ u não có nên tự ý mua các loại thuốc bổ não, hoạt huyết dưỡng não (như Ginkgo Biloba) uống thêm không?', 'Theo cảnh báo từ Vinmec và Bệnh viện Đa khoa Tâm Anh, tuyệt đối KHÔNG tự ý uống Ginkgo Biloba, Cerebrolysin hoặc An cung ngưu hoàng. Ginkgo Biloba có đặc tính chống đông máu, làm tăng nguy cơ chảy máu tái phát tại giường mổ; ngoài ra các thuốc này có thể tương tác làm giảm nồng độ thuốc chống động kinh, gây nguy hiểm cho tính mạng.', 'Bệnh viện Đa khoa Quốc tế Vinmec & BV Tâm Anh — Cảnh báo nguy cơ xuất huyết não khi tự ý dùng thuốc hoạt huyết sau phẫu thuật thần kinh (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau mổ u não có nên tự ý mua các loại thuốc bổ não, hoạt huyết dưỡng não (như Ginkgo Biloba) uống thêm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh u não có cần ăn kiêng tuyệt đối đường và thịt đỏ để ''bỏ đói tế bào ung thư'' không?', 'Theo tài liệu từ Duke University và Vinmec, đây là quan niệm sai lầm và nguy hại. Nhịn ăn khắt khe sẽ khiến cơ thể suy mòn, tụt giảm bạch cầu và không đủ sức đề kháng để vượt qua các đợt xạ trị, hóa trị. Tế bào não khỏe mạnh cũng cần glucose để tồn tại; người bệnh chỉ cần giảm đường ngọt nhân tạo và duy trì chế độ dinh dưỡng cân đối giàu protein nạc.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Bác bỏ quan niệm ăn kiêng bỏ đói khối u trong điều trị ung bướu thần kinh (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh u não có cần ăn kiêng tuyệt đối đường và thịt đỏ để ''bỏ đói tế bào ung thư'' không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Uống thuốc hóa trị Temozolomide bị buồn nôn và mệt mỏi nhiều thì nên làm gì để giảm bớt?', 'Theo Duke University và Mayo Clinic: (1) Bệnh nhân nên uống thuốc chống nôn (Ondansetron) trước khi uống Temozolomide khoảng 30-60 phút theo toa bác sĩ; (2) Nên uống Temozolomide vào buổi tối ngay trước khi đi ngủ lúc dạ dày rỗng (sau ăn tối 2 tiếng) để người bệnh ngủ thiếp đi và giảm cảm giác nôn nao; (3) Uống trọn viên thuốc với nước lọc, không nhai vỡ.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Hướng dẫn giảm thiểu tác dụng phụ đường tiêu hóa khi điều trị Temozolomide (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Uống thuốc hóa trị Temozolomide bị buồn nôn và mệt mỏi nhiều thì nên làm gì để giảm bớt?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Trong quá trình hóa trị mà xét nghiệm thấy bạch cầu bị tụt giảm, gia đình cần chăm sóc phòng ngừa nhiễm trùng ra sao?', 'Theo Duke University và Vinmec, khi hạ bạch cầu hạt (Neutropenia), hệ miễn dịch rất yếu. Gia đình cần: (1) Cho bệnh nhân ăn chín uống sôi 100%, không ăn rau sống, gỏi, hoa quả chưa gọt vỏ; (2) Đeo khẩu trang, tránh tiếp xúc người đang bị cảm cúm hoặc nơi đông người; (3) Đo nhiệt độ hàng ngày và đưa đi cấp cứu ngay nếu người bệnh sốt từ 38 độ C trở lên.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Hướng dẫn chăm sóc và phòng ngừa nhiễm trùng khi hạ bạch cầu trong hóa trị u não (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Trong quá trình hóa trị mà xét nghiệm thấy bạch cầu bị tụt giảm, gia đình cần chăm sóc phòng ngừa nhiễm trùng ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao càng về những tuần cuối của đợt xạ trị người bệnh càng cảm thấy kiệt sức và buồn ngủ li bì?', 'Theo Duke University và Mayo Clinic, đây là hiện tượng ''mệt mỏi do bức xạ tích lũy'' (Radiation fatigue). Cơ thể phải tiêu tốn lượng năng lượng khổng lồ để liên tục sửa chữa và tái tạo các tế bào lành xung quanh vùng chiếu xạ. Tình trạng này là sinh lý tự nhiên, người bệnh nên ngủ nghỉ nhiều hơn và cảm giác này sẽ biến mất sau khi đợt xạ trị kết thúc vài tuần.', 'Tisch Brain Tumor Center - Duke University & Mayo Clinic — Cơ chế và cách đối phó với chứng mệt mỏi tích lũy do xạ trị hệ thần kinh (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao càng về những tuần cuối của đợt xạ trị người bệnh càng cảm thấy kiệt sức và buồn ngủ li bì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau phẫu thuật hoặc điều trị u não bao lâu thì người bệnh có thể sinh hoạt tình dục an toàn?', 'Theo Mayo Clinic và Bệnh viện Đa khoa Tâm Anh, thông thường người bệnh có thể sinh hoạt tình dục nhẹ nhàng trở lại sau mổ khoảng 4 đến 6 tuần, khi vết mổ đã lành và không còn đau đầu hay chóng mặt. Tránh các tư thế gây căng thẳng vùng cổ đầu và dừng lại ngay nếu thấy đau nhức đầu.', 'Mayo Clinic & Bệnh viện Đa khoa Tâm Anh — Tái lập sinh hoạt đời sống vợ chồng sau điều trị u não (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau phẫu thuật hoặc điều trị u não bao lâu thì người bệnh có thể sinh hoạt tình dục an toàn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ u não hay bị mất ngủ, cáu gắt hoặc trầm cảm thì người nhà cần làm gì để hỗ trợ tâm lý?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, sự thay đổi cảm xúc này xuất phát từ tâm lý lo âu kết hợp tổn thương thực thể thần kinh hoặc tác dụng phụ của thuốc corticoid. Gia đình cần: Lắng nghe kiên nhẫn, không tranh cãi hay chỉ trích; tạo không gian yên tĩnh, hỗ trợ người bệnh đi dạo thư giãn ngoài trời; và báo cho bác sĩ điều trị để được kê thêm thuốc hỗ trợ an toàn.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Chăm sóc sức khỏe tâm thần và tâm lý cho bệnh nhân sau tổn thương sọ não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ u não hay bị mất ngủ, cáu gắt hoặc trầm cảm thì người nhà cần làm gì để hỗ trợ tâm lý?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau mổ u não xuất viện về nhà nếu còn đau đầu âm ỉ thì có thể uống thuốc giảm đau gì an toàn?', 'Theo Vinmec và Bệnh viện Đa khoa Tâm Anh, thuốc giảm đau an toàn và thông dụng nhất là Paracetamol (500mg mỗi lần, cách nhau 4-6 giờ, tối đa 3000mg/ngày). TUYỆT ĐỐI KHÔNG tự ý uống Aspirin hoặc Ibuprofen vì làm tăng nguy cơ chảy máu trong não. Nếu đau đầu dữ dội kèm nôn ói, cần quay lại bệnh viện tái khám ngay.', 'Bệnh viện Đa khoa Quốc tế Vinmec & BV Tâm Anh — Sử dụng thuốc giảm đau an toàn sau phẫu thuật sọ não tại nhà (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau mổ u não xuất viện về nhà nếu còn đau đầu âm ỉ thì có thể uống thuốc giảm đau gì an toàn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bệnh nhân sau phẫu thuật u não bao lâu thì có thể quay lại làm việc và cần tránh những việc gì?', 'Theo Mayo Clinic và Vinmec, thời gian quay lại công việc thường từ 6 đến 12 tuần sau mổ: Với công việc văn phòng nhẹ nhàng, người bệnh có thể bắt đầu làm việc bán thời gian (nửa ngày) trước; tuyệt đối tránh các công việc mang vác nặng, làm việc trên cao, vận hành máy móc nguy hiểm hoặc làm việc ca đêm gây căng thẳng thần kinh quá mức.', 'Mayo Clinic & Vinmec — Đánh giá khả năng lao động và tái hòa nhập công việc sau phẫu thuật thần kinh (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bệnh nhân sau phẫu thuật u não bao lâu thì có thể quay lại làm việc và cần tránh những việc gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ u não có được cúi gập người sâu hoặc tập các bài tập thể thao gắng sức không?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, trong 2 đến 3 tháng đầu sau mổ, tuyệt đối KHÔNG ĐƯỢC cúi gập đầu sâu xuống thấp (như cúi nhặt đồ sát đất), không nín thở rặn mạnh và không tập gym, nâng tạ. Động tác cúi đầu và rặn mạnh sẽ làm tăng vọt áp lực tĩnh mạch trong sọ, có thể gây rách màng cứng, rò dịch não tủy hoặc tái phát xuất huyết não.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Các tư thế và vận động cần kiêng cữ nghiêm ngặt sau phẫu thuật sọ não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ u não có được cúi gập người sâu hoặc tập các bài tập thể thao gắng sức không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh u não bị lên cơn co giật trong lúc đang ngủ say thì người nhà cần xử trí tại chỗ như thế nào?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, khi phát hiện người bệnh co giật trong lúc ngủ: (1) Lập tức nghiêng toàn bộ người bệnh sang một bên (tư thế nằm nghiêng an toàn) để đờm dãi, chất nôn tự chảy ra ngoài, tránh sặc vào đường thở; (2) Kê gối mềm dưới đầu, dẹp bỏ vật cứng nhọn xung quanh; (3) TUYỆT ĐỐI không ghì chặt tay chân, không nhét bất cứ vật gì vào miệng người bệnh; (4) Ghi nhớ thời gian cơn giật và gọi cấp cứu 115 nếu cơn giật kéo dài trên 3 phút hoặc tái diễn liên tục.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Hướng dẫn người nhà xử trí cơn co giật ban đêm ở bệnh nhân u não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh u não bị lên cơn co giật trong lúc đang ngủ say thì người nhà cần xử trí tại chỗ như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Cách chăm sóc, lăn trở người bệnh nằm liệt một bên sau mổ não để phòng ngừa loét tì đè vùng lưng mông?', 'Theo Bệnh viện Đa khoa Tâm Anh, người bệnh nằm liệt cần được: (1) Thay đổi tư thế nằm (nghiêng trái, nằm ngửa, nghiêng phải) đều đặn mỗi 2 giờ một lần; (2) Sử dụng đệm hơi chống loét hoặc lót gối mềm ở các điểm tì đè (xương cùng cụt, gót chân, mắt cá); (3) Vệ sinh da khô ráo, xoa bóp nhẹ nhàng bằng kem dưỡng ẩm và thay ga trải giường ngay khi bị ẩm ướt để bảo vệ toàn vẹn làn da.', 'Bệnh viện Đa khoa Tâm Anh — Kỹ thuật chăm sóc và chống loét tì đè cho bệnh nhân liệt sau phẫu thuật thần kinh (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Cách chăm sóc, lăn trở người bệnh nằm liệt một bên sau mổ não để phòng ngừa loét tì đè vùng lưng mông?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ hoặc đang truyền hóa chất bị chán ăn, ăn vào là buồn nôn thì gia đình nên chế biến thức ăn thế nào?', 'Theo Duke University và Vinmec, gia đình nên: (1) Chia nhỏ bữa ăn thành 5-6 bữa nhẹ trong ngày thay vì 3 bữa lớn; (2) Chế biến món ăn dạng mềm, lỏng, nguội hoặc ấm nhẹ (như súp gà, cháo thịt băm, sinh tố) vì thức ăn nóng bốc mùi nồng dễ kích thích cảm giác buồn nôn; (3) Cho người bệnh ngậm một lát gừng tươi hoặc uống vài ngụm nước ấm trước bữa ăn 30 phút để dịu dạ dày.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Hướng dẫn dinh dưỡng và chế biến món ăn giảm cảm giác buồn nôn cho người bệnh (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ hoặc đang truyền hóa chất bị chán ăn, ăn vào là buồn nôn thì gia đình nên chế biến thức ăn thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh u não có ăn được yến sào, đông trùng hạ thảo hoặc uống sữa công thức cao năng lượng không?', 'Theo Vinmec và Mayo Clinic, người bệnh hoàn toàn có thể dùng yến sào, đông trùng hạ thảo và các loại sữa chuyên biệt (như Prosure, Fortimel) để bồi bổ phục hồi thể trạng, tăng lượng đạm và vi chất quý. Tuy nhiên, các thực phẩm này chỉ đóng vai trò hỗ trợ dinh dưỡng nâng cao đề kháng, không có tác dụng tiêu diệt khối u và không thể thay thế cho các bữa ăn chính hay phác đồ điều trị của bác sĩ.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Mayo Clinic — Sử dụng thực phẩm bồi bổ và sữa chuyên biệt an toàn cho bệnh nhân ung bướu thần kinh (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh u não có ăn được yến sào, đông trùng hạ thảo hoặc uống sữa công thức cao năng lượng không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bệnh nhân sau phẫu thuật u não bị bí tiểu hoặc tiểu tiện không tự chủ thì gia đình cần xử trí ra sao?', 'Theo Bệnh viện Đa khoa Tâm Anh và Johns Hopkins, rối loạn tiểu tiện sau mổ não có thể do thuốc mê, tổn thương trung tâm điều khiển bàng quang ở thùy trán hoặc tác dụng phụ thuốc. Nếu bí tiểu (bụng dưới căng cứng, tức khó chịu không đi được), gia đình cần báo ngay điều dưỡng để đặt ống thông tiểu giải áp; nếu són tiểu không tự chủ, cần đóng bỉm vệ sinh sạch sẽ tránh viêm đường tiết niệu và tập bàng quang theo giờ.', 'Bệnh viện Đa khoa Tâm Anh & Johns Hopkins — Chăm sóc và phục hồi chức năng bàng quang sau phẫu thuật thần kinh (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bệnh nhân sau phẫu thuật u não bị bí tiểu hoặc tiểu tiện không tự chủ thì gia đình cần xử trí ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Những dấu hiệu nguy hiểm nào xuất hiện tại nhà mà gia đình bắt buộc phải gọi xe cấp cứu 115 đưa đi viện ngay?', 'Theo Vinmec và Mayo Clinic, gia đình phải đưa bệnh nhân đi cấp cứu ngay lập tức khi có 1 trong 5 dấu hiệu báo động đỏ: (1) Cơn co giật kéo dài trên 3 phút hoặc co giật nhiều lần liên tiếp không tỉnh; (2) Đau đầu dữ dội đột ngột kèm nôn vọt liên tục; (3) Liệt tăng đột ngột một bên người hoặc méo miệng, nói ngọng bất thường; (4) Người bệnh lơ mơ, lay gọi không tỉnh (hôn mê); (5) Sốt cao trên 38.5 độ C kèm vết mổ rỉ dịch mủ hoặc cứng gáy.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Mayo Clinic — Nhận biết các tình huống khẩn cấp cần đưa bệnh nhân u não đi cấp cứu ngay (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Những dấu hiệu nguy hiểm nào xuất hiện tại nhà mà gia đình bắt buộc phải gọi xe cấp cứu 115 đưa đi viện ngay?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người nhà cần quan sát những thay đổi nhỏ nào hàng ngày để phát hiện sớm nguy cơ khối u tái phát trở lại?', 'Theo Duke University và Johns Hopkins, khối u tái phát thường biểu hiện bằng sự quay trở lại của các triệu chứng cũ hoặc triệu chứng mới từ từ: (1) Đau đầu tăng dần trở lại, nhất là vào sáng sớm khi ngủ dậy; (2) Tay chân bên yếu ngày càng vụng về hơn (như hay đánh rơi cốc, đi bước hụt); (3) Thay đổi tính tình, thờ ơ hoặc hay quên hơn; (4) Tái xuất hiện các cơn giật cơ nhẹ ở khóe miệng hoặc ngón tay. Khi thấy các dấu hiệu này, cần đưa người bệnh chụp MRI kiểm tra sớm.', 'Tisch Brain Tumor Center - Duke University & Johns Hopkins — Hướng dẫn gia đình theo dõi và phát hiện sớm các dấu hiệu u não tái phát (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người nhà cần quan sát những thay đổi nhỏ nào hàng ngày để phát hiện sớm nguy cơ khối u tái phát trở lại?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ não nếu vô tình bị va chạm nhẹ vùng đầu vào cạnh giường hoặc cửa thì theo dõi thế nào?', 'Theo Vinmec và Johns Hopkins, nắp sọ đã được cố định bằng nẹp Titan nên các va chạm nhẹ thông thường không làm di lệch xương. Tuy nhiên, gia đình cần theo dõi sát bệnh nhân trong 48 giờ: Nếu người bệnh chỉ đau nhẹ tại chỗ rồi hết thì không đáng lo; nhưng nếu xuất hiện đau đầu tăng dữ dội, buồn nôn, lơ mơ, chảy dịch mũi/tai hoặc vết mổ sưng phồng lên thì phải đến bệnh viện chụp CT kiểm tra ngay để loại trừ chảy máu tái phát.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Johns Hopkins — Xử trí và theo dõi chấn thương va đập nhẹ vùng đầu sau phẫu thuật sọ não (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ não nếu vô tình bị va chạm nhẹ vùng đầu vào cạnh giường hoặc cửa thì theo dõi thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sau mổ u não bao lâu thì người bệnh có thể sấy tóc, nhuộm tóc hoặc uốn tóc thẩm mỹ?', 'Theo Johns Hopkins và Vinmec, bệnh nhân có thể sấy tóc ở chế độ GIÓ MÁT sau khi cắt chỉ 1-2 tuần. Riêng các thủ thuật làm đẹp sử dụng hóa chất mạnh (như nhuộm tóc, tẩy tóc, uốn ép nhiệt), người bệnh nên kiêng ít nhất 3 đến 6 tháng cho đến khi sẹo mổ liền xương vững chắc và da đầu không còn nhạy cảm; hóa chất nhuộm có thể gây kích ứng bỏng rát hoặc viêm nhiễm vùng da đầu phẫu thuật.', 'Johns Hopkins Medicine & Vinmec — Thời gian an toàn cho các dịch vụ chăm sóc tóc và thẩm mỹ sau mổ sọ não (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sau mổ u não bao lâu thì người bệnh có thể sấy tóc, nhuộm tóc hoặc uốn tóc thẩm mỹ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh u não có được tắm nước quá nóng, ngâm bồn nước nóng hoặc đi xông hơi (sauna) không?', 'Theo Bệnh viện Đa khoa Tâm Anh và Mayo Clinic, người bệnh u não KHÔNG NÊN ngâm bồn nước quá nóng hoặc đi xông hơi (sauna). Nhiệt độ môi trường tăng cao làm giãn nở các mạch máu toàn thân, gây hạ huyết áp đột ngột dẫn đến choáng váng ngất xỉu, đồng thời sự thay đổi thân nhiệt quá mức có thể kích hoạt cơn co giật động kinh ở những người có tổn thương vỏ não.', 'Bệnh viện Đa khoa Tâm Anh & Mayo Clinic — Những lưu ý khi tắm rửa và kiêng cữ xông hơi ở bệnh nhân sau mổ u não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh u não có được tắm nước quá nóng, ngâm bồn nước nóng hoặc đi xông hơi (sauna) không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau phẫu thuật u não có được dùng điện thoại thông minh, xem tivi nhiều không?', 'Theo Mayo Clinic và Vinmec, trong 2-4 tuần đầu sau mổ, người bệnh nên hạn chế nhìn màn hình điện thoại, máy tính và tivi quá lâu (chỉ nên xem 15-20 phút rồi nghỉ ngơi). Ánh sáng xanh chớp nháy và việc điều tiết mắt liên tục có thể gây mỏi mắt, nhức đầu và kích thích thần kinh não bộ đang trong giai đoạn hồi phục nhạy cảm.', 'Mayo Clinic & Vinmec — Quản lý thời gian sử dụng thiết bị điện tử và chăm sóc thị giác sau phẫu thuật não (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau phẫu thuật u não có được dùng điện thoại thông minh, xem tivi nhiều không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người nhà trực tiếp chăm sóc bệnh nhân u não (caregiver) bị kiệt sức, lo âu stress nặng thì có lời khuyên nào?', 'Theo Duke University và Bệnh viện Đa khoa Tâm Anh, hội chứng kiệt sức ở người chăm sóc (Caregiver Burnout) rất phổ biến. Lời khuyên cho gia đình: (1) Chia sẻ gánh nặng chăm sóc giữa các thành viên trong gia đình, không để một người gánh vác đơn độc; (2) Dành thời gian nghỉ ngơi ít nhất 1-2 giờ mỗi ngày cho bản thân; (3) Tham gia các hội nhóm hỗ trợ gia đình bệnh nhân để giải tỏa tâm lý; (4) Đừng ngần ngại nhờ chuyên gia tâm lý tư vấn khi thấy dấu hiệu mất ngủ, kiệt quệ tinh thần.', 'Tisch Brain Tumor Center - Duke University & BV Tâm Anh — Hỗ trợ tâm lý và phòng ngừa hội chứng kiệt sức cho người chăm sóc bệnh nhân u não (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người nhà trực tiếp chăm sóc bệnh nhân u não (caregiver) bị kiệt sức, lo âu stress nặng thì có lời khuyên nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh trở nên vô cảm, hay quên tên con cháu hoặc thay đổi tính nết sau mổ thì có hồi phục được không?', 'Theo Bệnh viện Đa khoa Tâm Anh và Vinmec, tình trạng này thường do phù não tạm thời sau mổ hoặc tổn thương vùng trán - thái dương. Khoảng 70-80% bệnh nhân sẽ cải thiện dần tính cách và trí nhớ sau 3-6 tháng khi phù não rút hết. Gia đình cần: Kiên nhẫn nhắc lại kỷ niệm và tên người thân bằng giọng điệu êm dịu, không to tiếng hay bắt ép người bệnh phải nhớ, tạo môi trường sống ấm áp quen thuộc.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Hướng dẫn gia đình ứng xử và chăm sóc khi bệnh nhân bị biến đổi tính cách sau phẫu thuật (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh trở nên vô cảm, hay quên tên con cháu hoặc thay đổi tính nết sau mổ thì có hồi phục được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chi phí điều trị u não thường bao gồm những khoản nào và Bảo hiểm Y tế (BHYT) chi trả những gì?', 'Theo quy định Bảo hiểm Y tế và hướng dẫn bệnh viện: BHYT chi trả phần lớn chi phí giường bệnh, xét nghiệm máu, chụp MRI chẩn đoán, công phẫu thuật và thuốc hóa trị nằm trong danh mục (như Temozolomide được đồng chi trả theo tỷ lệ). Các khoản gia đình cần chuẩn bị đồng chi trả gồm: vật tư tiêu hao kỹ thuật cao (như nẹp vít Titan, dao mổ vi phẫu siêu âm CUSA, keo sinh học dán màng não) và thuốc ngoài danh mục BHYT.', 'Bệnh viện Đa khoa Quốc tế Vinmec — Chính sách chi trả bảo hiểm y tế và cơ cấu chi phí điều trị phẫu thuật thần kinh (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chi phí điều trị u não thường bao gồm những khoản nào và Bảo hiểm Y tế (BHYT) chi trả những gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chăm sóc giảm nhẹ tại nhà cho bệnh nhân u não giai đoạn muộn cần chú ý những gì để người bệnh bớt đau đớn?', 'Theo Duke University và Vinmec, chăm sóc giảm nhẹ giai đoạn muộn tập trung vào kiểm soát triệu chứng và chất lượng sống: (1) Tuân thủ lịch dùng thuốc giảm đau bậc cao (morphin/dẫn xuất) theo toa chuyên khoa để người bệnh không bị cơn đau hành hạ; (2) Giữ tư thế đầu cao 30 độ giúp giảm áp lực nội sọ; (3) Hút đờm dãi, chăm sóc da chống loét; (4) Luôn có người thân túc trực trò chuyện, nắm tay để người bệnh cảm nhận sự bình yên và yêu thương.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Chăm sóc giảm nhẹ và kiểm soát cơn đau toàn diện cho bệnh nhân u não giai đoạn tiến triển (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chăm sóc giảm nhẹ tại nhà cho bệnh nhân u não giai đoạn muộn cần chú ý những gì để người bệnh bớt đau đớn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh sau mổ não có được đi chùa, đi lễ hoặc đi du lịch xa bằng ô tô không?', 'Theo Bệnh viện Đa khoa Tâm Anh, sau mổ 4-6 tuần khi sức khỏe ổn định, người bệnh có thể đi lễ chùa nhẹ nhàng hoặc đi du lịch gần bằng ô tô để thư giãn tinh thần. Tuy nhiên, người nhà cần lưu ý: (1) Không đi đường đèo dốc quanh co gây chóng mặt say xe; (2) Tránh những nơi chen chúc xô đẩy ngột ngạt thiếu oxy; (3) Luôn mang theo đầy đủ thuốc chống co giật và thuốc giảm đau trong túi xách tay; (4) Cho người bệnh nghỉ ngơi ngay khi thấy thấm mệt.', 'Bệnh viện Đa khoa Tâm Anh — Lưu ý an toàn khi cho bệnh nhân sau phẫu thuật não tham gia các hoạt động du lịch và tâm linh (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'treatment_care'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh sau mổ não có được đi chùa, đi lễ hoặc đi du lịch xa bằng ô tô không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh có các triệu chứng nghi ngờ u não (đau đầu dữ dội, nôn vọt, co giật) thì nên đăng ký khám chuyên khoa nào đầu tiên?', 'Người bệnh nên đăng ký khám tại chuyên khoa Nội Thần kinh hoặc Ngoại Thần kinh (Phẫu thuật Thần kinh) tại các bệnh viện đa khoa tuyến tỉnh hoặc tuyến trung ương. Bác sĩ chuyên khoa Thần kinh sẽ trực tiếp thăm khám phản xạ, thị lực, tri giác và chỉ định chụp MRI sọ não phù hợp nhất để xác định hoặc loại trừ tổn thương choán chỗ trong hộp sọ.', 'Bệnh viện Bạch Mai & Bệnh viện Hữu nghị Việt Đức — Hướng dẫn người bệnh lựa chọn chuyên khoa thăm khám bệnh lý thần kinh sọ não (https://bachmai.gov.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh có các triệu chứng nghi ngờ u não (đau đầu dữ dội, nôn vọt, co giật) thì nên đăng ký khám chuyên khoa nào đầu tiên?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh cần chuẩn bị những giấy tờ, hồ sơ bệnh án và vật dụng gì trước khi đi khám chuyên khoa Thần kinh?', 'Người bệnh và người nhà cần chuẩn bị: (1) Căn cước công dân gắn chip hoặc ứng dụng VNeID; (2) Thẻ Bảo hiểm Y tế và giấy chuyển tuyến (nếu có); (3) Toàn bộ hồ sơ bệnh án cũ, toa thuốc đang sử dụng, kết quả xét nghiệm máu gần nhất; (4) Đĩa CD/DVD hoặc phim chụp X-quang, CT, MRI trước đây (nếu có) để bác sĩ so sánh tiến triển tổn thương; (5) Ghi sẵn ra giấy các câu hỏi thắc mắc và nhật ký các triệu chứng bất thường (thời gian khởi phát, tần suất đau đầu, cơn co giật).', 'Bệnh viện Đa khoa Quốc tế Vinmec — Những điều người bệnh cần chuẩn bị trước khi khám chuyên khoa thần kinh (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh cần chuẩn bị những giấy tờ, hồ sơ bệnh án và vật dụng gì trước khi đi khám chuyên khoa Thần kinh?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chụp MRI sọ não có bắt buộc phải nhịn ăn uống không? Khi nào cần nhịn ăn trước khi chụp?', 'Theo quy chuẩn chẩn đoán hình ảnh: Nếu chụp MRI sọ não thông thường KHÔNG tiêm thuốc đối quang từ, người bệnh không cần nhịn ăn. Tuy nhiên, nếu nghi ngờ u não và có chỉ định TIÊM THUỐC ĐỐI QUANG TỪ (Gadolinium) hoặc cần GÂY MÊ (cho trẻ em, người kích động), người bệnh bắt buộc phải nhịn ăn ít nhất 4 đến 6 giờ trước khi chụp để phòng ngừa biến chứng nôn sặc chất nôn vào phổi; người bệnh vẫn có thể uống một lượng nhỏ nước lọc trước giờ chụp 2 tiếng.', 'Bệnh viện Đa khoa Tâm Anh & Vinmec — Quy tắc nhịn ăn và chuẩn bị an toàn trước khi chụp cộng hưởng từ MRI sọ não (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chụp MRI sọ não có bắt buộc phải nhịn ăn uống không? Khi nào cần nhịn ăn trước khi chụp?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Những thiết bị kim loại hoặc cấy ghép nào trong cơ thể là CHỐNG CHỈ ĐỊNH hoặc cần hết sức lưu ý khi chụp MRI sọ não?', 'Từ trường máy MRI rất mạnh (1.5 Tesla - 3.0 Tesla), do đó: (1) CHỐNG CHỈ ĐỊNH TUYỆT ĐỐI với bệnh nhân có máy tạo nhịp tim cũ (loại không tương thích MRI - non-MRI conditional), máy khử rung tim tự động ICD, kẹp phình mạch não bằng kim loại từ tính (ferromagnetic clip), máy ốc tai điện tử và dị vật kim khí trong nhãn cầu mắt; (2) CẦN THÔNG BÁO RÕ để bác sĩ kiểm tra thẻ an toàn với: nẹp vít xương Titan, van tim nhân tạo, máy bơm tiêm tự động và thiết bị thần kinh cấy ghép.', 'Bệnh viện Hữu nghị Việt Đức & Mayo Clinic — Bảng kiểm tra an toàn kim loại và chống chỉ định phòng chụp cộng hưởng từ (https://benhvienvietduc.org)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Những thiết bị kim loại hoặc cấy ghép nào trong cơ thể là CHỐNG CHỈ ĐỊNH hoặc cần hết sức lưu ý khi chụp MRI sọ não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người đang niềng răng mắc cài kim loại hoặc cấy ghép răng Implant nha khoa có chụp MRI sọ não được không?', 'Người cấy ghép Implant nha khoa hoặc niềng răng HOÀN TOÀN CÓ THỂ chụp MRI an toàn vì hầu hết vật liệu nha khoa hiện đại được chế tạo từ Titanium hoặc sứ cao cấp không có từ tính mạnh, không bị lực hút nam châm kéo bật ra. Tuy nhiên, kim loại ở hàm mặt có thể tạo hiện tượng xảo ảnh (artifact) gây nhiễu mờ một phần cấu trúc đáy sọ hoặc xương hàm. Người bệnh phải khai báo với kỹ thuật viên để tối ưu hóa chuỗi xung chụp giảm nhiễu.', 'Bệnh viện Đa khoa Tâm Anh — Niềng răng và cấy ghép Implant có chụp MRI sọ não an toàn được không? (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người đang niềng răng mắc cài kim loại hoặc cấy ghép răng Implant nha khoa có chụp MRI sọ não được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người mắc hội chứng sợ không gian hẹp kín (Claustrophobia) hoặc quá lo lắng hoảng loạn khi vào lồng máy MRI thì bệnh viện hỗ trợ thế nào?', 'Các bệnh viện hiện đại có nhiều giải pháp hỗ trợ: (1) Sử dụng hệ thống máy MRI thế hệ mới có đường kính khoang chụp rộng (70cm) tạo cảm giác thông thoáng; (2) Sử dụng gương góc nghiêng giúp bệnh nhân nhìn thấy hình ảnh bên ngoài lồng chụp; (3) Cung cấp tai nghe phát nhạc êm dịu cách âm tiếng ồn máy gõ; (4) Trao quả bóng cao su bóp báo động cầm tay (bệnh nhân bóp bóng là máy dừng ngay lập tức); (5) Bác sĩ có thể chỉ định dùng thuốc an thần nhẹ đường uống trước chụp 30 phút để giúp người bệnh thả lỏng tâm lý.', 'Bệnh viện Đa khoa Quốc tế Vinmec & Mayo Clinic — Giải pháp cho người mắc hội chứng sợ không gian kín khi chụp cộng hưởng từ (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người mắc hội chứng sợ không gian hẹp kín (Claustrophobia) hoặc quá lo lắng hoảng loạn khi vào lồng máy MRI thì bệnh viện hỗ trợ thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phụ nữ đang mang thai hoặc đang trong giai đoạn cho con bú có chụp MRI não và tiêm thuốc đối quang từ được không?', 'Theo khuyến cáo của Hiệp hội Điện quang Hoa Kỳ (ACR) và Vinmec: (1) Chụp MRI sọ não KHÔNG dùng tia X bức xạ ion hóa nên không gây hại thai nhi như chụp CT hay X-quang, tuy nhiên thường ưu tiên chụp từ tam cá nguyệt thứ hai trở đi; (2) Thuốc đối quang từ Gadolinium KHÔNG ĐƯỢC KHUYẾN CÁO tiêm cho phụ nữ mang thai trừ tình huống khẩn cấp đe dọa tính mạng; (3) Với phụ nữ đang cho con bú, lượng Gadolinium tiết vào sữa mẹ cực nhỏ (<0.04%), người mẹ có thể tiếp tục cho con bú hoặc cẩn thận hơn thì vắt bỏ sữa trong 24 giờ sau tiêm.', 'Bệnh viện Đa khoa Quốc tế Vinmec & ACR — Hướng dẫn chụp cộng hưởng từ và sử dụng thuốc đối quang ở phụ nữ có thai và cho con bú (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phụ nữ đang mang thai hoặc đang trong giai đoạn cho con bú có chụp MRI não và tiêm thuốc đối quang từ được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Trẻ em hoặc người bệnh rối loạn tâm thần, co giật không chịu nằm yên trong máy MRI thì bệnh viện xử trí như thế nào?', 'Chụp MRI sọ não yêu cầu giữ bất động tuyệt đối trong 20-30 phút. Đối với trẻ nhỏ hoặc bệnh nhân kích động, bệnh viện sẽ phối hợp cùng bác sĩ Gây mê hồi sức thực hiện kỹ thuật tiền mê hoặc an thần nhẹ/gây mê đường tĩnh mạch ngắn: Bệnh nhân ngủ êm dịu trong suốt quá trình chụp, có máy theo dõi nhịp tim SpO2 liên tục và tỉnh lại hoàn toàn bình thường sau khi kết thúc ca chụp 15-30 phút.', 'Bệnh viện Nhi Đồng 1 & Bệnh viện Đa khoa Tâm Anh — Quy trình gây mê an thần hỗ trợ chụp cộng hưởng từ cho trẻ em và người bệnh khó hợp tác (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Trẻ em hoặc người bệnh rối loạn tâm thần, co giật không chịu nằm yên trong máy MRI thì bệnh viện xử trí như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao trước khi chụp MRI sọ não có tiêm thuốc đối quang từ Gadolinium, bác sĩ bắt buộc phải xét nghiệm máu kiểm tra chức năng thận?', 'Thuốc đối quang từ Gadolinium được bài tiết chủ yếu qua đường thận. Ở những người bệnh bị suy thận nặng mạn tính (độ lọc cầu thận eGFR < 30 mL/phút/1.73m2), việc tiêm Gadolinium có thể dẫn đến biến chứng hiếm gặp nhưng rất nguy hiểm là bệnh xơ hóa toàn thân do thận (Nephrogenic Systemic Fibrosis - NSF). Do đó, xét nghiệm nồng độ Ure, Creatinin và tính chỉ số eGFR là bắt buộc để đảm bảo thận đủ khả năng đào thải thuốc an toàn.', 'Bệnh viện Chợ Rẫy & Bệnh viện Bạch Mai — Chỉ định đánh giá chức năng thận trước sử dụng thuốc đối quang từ trong chẩn đoán hình ảnh (https://choray.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao trước khi chụp MRI sọ não có tiêm thuốc đối quang từ Gadolinium, bác sĩ bắt buộc phải xét nghiệm máu kiểm tra chức năng thận?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Quy trình khám lâm sàng của bác sĩ chuyên khoa Thần kinh bao gồm những bước kiểm tra cụ thể nào?', 'Bác sĩ chuyên khoa Thần kinh thực hiện theo trình tự y khoa: (1) Khai thác tiền sử bệnh, tính chất cơn đau đầu và co giật; (2) Đánh giá tri giác bằng thang điểm Glasgow (tri giác, định hướng thời gian, không gian); (3) Khám 12 đôi dây thần kinh sọ não (thị trường mắt, đồng tử, vận động nhãn cầu, cơ mặt, thính lực, nuốt); (4) Khám hệ vận động và cơ lực tay chân; (5) Khám phản xạ gân xương và phản xạ bệnh lý bó tháp (dấu hiệu Babinski); (6) Kiểm tra thăng bằng và phối hợp động tác (nghiệm pháp Romberg, ngón tay chỉ mũi).', 'Bệnh viện Hữu nghị Việt Đức & ĐH Y Dược TP.HCM — Quy trình kỹ thuật khám lâm sàng chuyên khoa thần kinh sọ não chuẩn Bộ Y tế (https://benhvienvietduc.org)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Quy trình khám lâm sàng của bác sĩ chuyên khoa Thần kinh bao gồm những bước kiểm tra cụ thể nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hội đồng hội chẩn đa chuyên khoa ung bướu thần kinh (Tumor Board) là gì và đóng vai trò gì trong phác đồ điều trị?', 'Hội đồng Tumor Board là cuộc hội chẩn liên chuyên khoa định kỳ gồm: Bác sĩ Ngoại thần kinh (phẫu thuật viên), Bác sĩ Ung bướu nội khoa (hóa trị), Bác sĩ Xạ trị, Bác sĩ Chẩn đoán hình ảnh (MRI/CT), Bác sĩ Giải phẫu bệnh và chuyên gia Phục hồi chức năng. Họ cùng ngồi lại phân tích toàn diện phim MRI, kết quả sinh thiết mô học và thể trạng bệnh nhân để thống nhất một phác đồ điều trị cá thể hóa tối ưu nhất, tránh phác đồ phiến diện từ một bác sĩ đơn lẻ.', 'Bệnh viện K Trung ương & Vinmec — Mô hình hội đồng hội chẩn đa chuyên khoa (Tumor Board) trong tối ưu hóa điều trị ung bướu (https://benhvienk.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hội đồng hội chẩn đa chuyên khoa ung bướu thần kinh (Tumor Board) là gì và đóng vai trò gì trong phác đồ điều trị?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người bệnh muốn xin ý kiến chuyên gia thứ hai (Second Opinion) về kết quả chẩn đoán và phim MRI u não thì cần chuẩn bị gì?', 'Ý kiến chuyên gia thứ hai là quyền lợi chính đáng của bệnh nhân. Để hội chẩn hiệu quả, gia đình cần chuẩn bị: (1) Toàn bộ file ảnh gốc định dạng DICOM của lần chụp MRI gần nhất (chép trên đĩa CD/DVD hoặc tải lên Google Drive); (2) Kết quả giải phẫu bệnh hoặc sinh thiết mô u (nếu đã mổ trước đó); (3) Báo cáo tóm tắt quá trình điều trị, các loại thuốc đã dùng và tình trạng lâm sàng hiện tại của người bệnh; sau đó đăng ký khám hội chẩn chuyên gia tại các bệnh viện tuyến trung ương.', 'Cleveland Clinic & Tisch Brain Tumor Center - Duke University — Hướng dẫn người bệnh tìm kiếm ý kiến chuyên gia y tế thứ hai an toàn và hiệu quả (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người bệnh muốn xin ý kiến chuyên gia thứ hai (Second Opinion) về kết quả chẩn đoán và phim MRI u não thì cần chuẩn bị gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Bệnh viện Hữu nghị Việt Đức (Hà Nội): Địa chỉ, số điện thoại, thế mạnh phẫu thuật thần kinh và kinh nghiệm đi khám?', 'Bệnh viện Hữu nghị Việt Đức là cái nôi phẫu thuật thần kinh hàng đầu cả nước: (1) Địa chỉ: 40 Tràng Thi, quận Hoàn Kiếm, Hà Nội; (2) Hotline cấp cứu & đặt lịch: 1900 1907 hoặc (024) 3825 3531; (3) Thế mạnh: Trung tâm Phẫu thuật Thần kinh chuyên sâu điều trị u màng não phức tạp, u thần kinh đệm lan tỏa, u nền sọ với công nghệ vi phẫu, kính vi phẫu tích hợp huỳnh quang 5-ALA và hệ thống Navigation 3D; (4) Kinh nghiệm khám: Nên đặt lịch khám theo yêu cầu tại nhà C4 để giảm thời gian chờ đợi.', 'Bệnh viện Hữu nghị Việt Đức — Giới thiệu Trung tâm Phẫu thuật Thần kinh - Bệnh viện Hữu nghị Việt Đức (https://benhvienvietduc.org)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Bệnh viện Hữu nghị Việt Đức (Hà Nội): Địa chỉ, số điện thoại, thế mạnh phẫu thuật thần kinh và kinh nghiệm đi khám?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Bệnh viện Bạch Mai (Hà Nội): Địa chỉ, khoa Thần kinh & Trung tâm Y học hạt nhân Dao Gamma, hướng dẫn quy trình khám?', 'Bệnh viện Bạch Mai là bệnh viện đa khoa hạng đặc biệt tuyến cuối miền Bắc: (1) Địa chỉ: 78 Đường Giải Phóng, phường Phương Mai, quận Đống Đa, Hà Nội; (2) Hotline: (024) 3869 3731; (3) Thế mạnh: Viện Thần kinh chuyên sâu chẩn đoán nội thần kinh phức tạp, và Trung tâm Y học hạt nhân & Ung bướu nổi tiếng với hệ thống xạ phẫu Dao Gamma quay (Rotating Gamma Knife) điều trị u não không cần mở hộp sọ; (4) Quy trình khám: Đăng ký tại Khoa Khám bệnh hoặc Khoa Khám bệnh theo yêu cầu (nhà K1), xuất trình BHYT đúng tuyến.', 'Bệnh viện Bạch Mai — Hướng dẫn khám chữa bệnh và điều trị u não bằng Dao Gamma tại Bệnh viện Bạch Mai (https://bachmai.gov.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Bệnh viện Bạch Mai (Hà Nội): Địa chỉ, khoa Thần kinh & Trung tâm Y học hạt nhân Dao Gamma, hướng dẫn quy trình khám?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Bệnh viện K Trung ương (Cơ sở Tân Triều - Hà Nội): Địa chỉ, chuyên khoa Ung bướu thần kinh và thế mạnh điều trị?', 'Bệnh viện K là cơ sở chuyên khoa ung bướu đầu ngành của cả nước: (1) Địa chỉ: Số 30 đường Cầu Bươu, huyện Thanh Trì, Hà Nội (Cơ sở 3 - Tân Triều); (2) Hotline: 1900 886 684 hoặc 0904 748 808; (3) Thế mạnh: Khoa Ngoại Thần kinh & Trung tâm Xạ trị chuyên sâu điều trị u não ác tính (u thần kinh đệm cấp độ cao, u nguyên bào tủy, u di căn não) bằng phẫu thuật kết hợp xạ trị điều biến liều (IMRT, VMAT) và hóa trị phác đồ Stupp với Temozolomide; (4) Đặt hẹn khám trực tuyến qua website hoặc ứng dụng Bệnh viện K.', 'Bệnh viện K Trung ương — Cổng thông tin và hướng dẫn khám chữa bệnh chuyên khoa ung bướu Bệnh viện K (https://benhvienk.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Bệnh viện K Trung ương (Cơ sở Tân Triều - Hà Nội): Địa chỉ, chuyên khoa Ung bướu thần kinh và thế mạnh điều trị?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Bệnh viện Chợ Rẫy (TP.HCM): Địa chỉ, hotline, khoa Ngoại Thần kinh tuyến cuối miền Nam và quy trình tiếp nhận?', 'Bệnh viện Chợ Rẫy là trung tâm y tế chuyên sâu hạng đặc biệt tuyến cuối khu vực phía Nam: (1) Địa chỉ: 201B Nguyễn Chí Thanh, Phường 12, Quận 5, TP.HCM; (2) Hotline cấp cứu: (028) 3855 4137 hoặc (028) 3855 4138; (3) Thế mạnh: Khoa Ngoại Thần kinh có số lượng ca phẫu thuật u sọ não lớn nhất miền Nam, trang bị đầy đủ kính vi phẫu độ phóng đại cao, hệ thống xạ phẫu Gamma Knife, phòng hồi sức thần kinh chuyên sâu; (4) Khám bệnh: Đăng ký tại Khoa Khám bệnh cổng số 1 (Nguyễn Chí Thanh) hoặc phòng khám chuyên gia.', 'Bệnh viện Chợ Rẫy — Giới thiệu Khoa Ngoại Thần kinh và hướng dẫn khám chữa bệnh tại Bệnh viện Chợ Rẫy (https://choray.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Bệnh viện Chợ Rẫy (TP.HCM): Địa chỉ, hotline, khoa Ngoại Thần kinh tuyến cuối miền Nam và quy trình tiếp nhận?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Bệnh viện Đại học Y Dược TP.HCM: Địa chỉ, chuyên khoa Ngoại Thần kinh, thế mạnh phẫu thuật u tuyến yên và MRI 3.0 Tesla?', 'Bệnh viện Đại học Y Dược TP.HCM là mô hình viện - trường đại học uy tín hàng đầu: (1) Địa chỉ: 215 Hồng Bàng, Phường 11, Quận 5, TP.HCM; (2) Hotline: (028) 3855 4269 hoặc Tổng đài chăm sóc khách hàng: 1900 7178; (3) Thế mạnh: Chuyên khoa Ngoại Thần kinh đặc biệt xuất sắc trong kỹ thuật mổ nội soi u tuyến yên qua xoang bướm (Endoscopic Endonasal Transsphenoidal Surgery) không để lại sẹo mặt; hệ thống MRI 3.0 Tesla độ phân giải cao; (4) Người bệnh nên đặt hẹn trước qua app ''UMC - Đăng ký khám bệnh online''.', 'Bệnh viện Đại học Y Dược TP.HCM — Thế mạnh chuyên sâu Khoa Ngoại Thần kinh - Bệnh viện Đại học Y Dược TP.HCM (https://bvdaihoc.com.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Bệnh viện Đại học Y Dược TP.HCM: Địa chỉ, chuyên khoa Ngoại Thần kinh, thế mạnh phẫu thuật u tuyến yên và MRI 3.0 Tesla?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Hệ thống Bệnh viện Đa khoa Tâm Anh (Hà Nội & TP.HCM): Địa chỉ, Trung tâm Thần kinh và công nghệ Robot mổ não Modus V Synaptive?', 'Bệnh viện Đa khoa Tâm Anh là đơn vị tiên phong ứng dụng công nghệ hiện đại hàng đầu: (1) Cơ sở Hà Nội: 108 Hoàng Như Tiếp, Bồ Đề, Long Biên - ĐT: (024) 3872 3872; Cơ sở TP.HCM: 2B Phổ Quang, Phường 2, Tân Bình - ĐT: (028) 7102 6789; (2) Hotline tư vấn: 1800 6858 (miễn cước); (3) Thế mạnh: Trung tâm Khoa học Thần kinh sở hữu Robot phẫu thuật não Modus V Synaptive ứng dụng trí tuệ nhân tạo AI đầu tiên tại Đông Nam Á, giúp tiếp cận chính xác các khối u não nằm sâu, bảo tồn tối đa dây thần kinh; MRI 3.0 Tesla cao cấp.', 'Bệnh viện Đa khoa Tâm Anh — Trung tâm Khoa học Thần kinh và đột phá Robot mổ não Modus V Synaptive tại BVĐK Tâm Anh (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Hệ thống Bệnh viện Đa khoa Tâm Anh (Hà Nội & TP.HCM): Địa chỉ, Trung tâm Thần kinh và công nghệ Robot mổ não Modus V Synaptive?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thông tin Hệ thống Y tế Vinmec (Hà Nội & TP.HCM): Địa chỉ, Trung tâm Ung bướu & Xạ trị, phòng mổ Hybrid và quy trình đặt hẹn?', 'Hệ thống Y tế Vinmec đạt chuẩn kiểm định chất lượng y tế quốc tế JCI: (1) Cơ sở Hà Nội: Vinmec Times City, 458 Minh Khai, Hai Bà Trưng, Hà Nội - ĐT: (024) 3974 3556; Cơ sở TP.HCM: Vinmec Central Park, 208 Nguyễn Hữu Cảnh, Bình Thạnh - ĐT: (028) 3622 1166; (2) Thế mạnh: Viện Ung bướu & Thần kinh trang bị phòng mổ thông minh Hybrid tích hợp chụp CT/MRI ngay trong mổ, máy xạ trị gia tốc Clinac iX thế hệ mới; (3) Dịch vụ: Đặt hẹn trước qua hotline 1900 232 389 hoặc app ''Vinmec'' để không phải chờ đợi.', 'Bệnh viện Đa khoa Quốc tế Vinmec — Trung tâm Ung bướu và Phẫu thuật Thần kinh chất lượng cao Hệ thống Y tế Vinmec (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thông tin Hệ thống Y tế Vinmec (Hà Nội & TP.HCM): Địa chỉ, Trung tâm Ung bướu & Xạ trị, phòng mổ Hybrid và quy trình đặt hẹn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thủ tục xin giấy chuyển tuyến Bảo hiểm Y tế (BHYT) từ tuyến dưới lên bệnh viện tuyến trung ương để điều trị u não như thế nào?', 'Theo quy định của Luật Bảo hiểm Y tế: (1) Người bệnh đến khám tại cơ sở đăng ký khám chữa bệnh ban đầu ghi trên thẻ BHYT (hoặc bệnh viện đa khoa tuyến huyện/tỉnh); (2) Nếu kết quả chẩn đoán hình ảnh (CT/MRI) hoặc lâm sàng nghi ngờ u não vượt quá năng lực điều trị của cơ sở, bác sĩ sẽ cấp ''Giấy chuyển tuyến khám bệnh, chữa bệnh BHYT'' lên bệnh viện tuyến cuối (như Việt Đức, Bạch Mai, Chợ Rẫy); (3) Khi có giấy chuyển tuyến đúng quy định, người bệnh sẽ được BHYT thanh toán đúng tuyến (từ 80% đến 100% theo mã thẻ BHYT).', 'Bảo hiểm Xã hội Việt Nam & Bộ Y tế — Hướng dẫn thủ tục chuyển tuyến khám chữa bệnh và quyền lợi Bảo hiểm Y tế (https://baohiemxahoi.gov.vn)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thủ tục xin giấy chuyển tuyến Bảo hiểm Y tế (BHYT) từ tuyến dưới lên bệnh viện tuyến trung ương để điều trị u não như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chi phí chụp MRI sọ não tại bệnh viện công lập và tư nhân hiện nay khoảng bao nhiêu tiền? BHYT chi trả như thế nào?', 'Mức giá chụp MRI sọ não tại Việt Nam tham khảo như sau: (1) Tại bệnh viện công lập: Chụp MRI không tiêm thuốc cản từ khoảng 1.300.000 - 1.800.000 VNĐ; nếu có tiêm thuốc cản từ khoảng 2.200.000 - 3.000.000 VNĐ (đã bao gồm thuốc). Nếu có BHYT đúng tuyến chi trả, người bệnh chỉ đồng chi trả một phần nhỏ theo mức hưởng (thường chỉ vài trăm nghìn đồng); (2) Tại bệnh viện tư nhân hoặc máy 3.0 Tesla cao cấp: Giá dịch vụ dao động từ 2.500.000 đến 4.500.000 VNĐ tùy gói chụp chuỗi xung chuyên sâu.', 'Bộ Y tế & Bệnh viện Đa khoa Tâm Anh — Khung giá dịch vụ khám chữa bệnh và chụp cộng hưởng từ MRI tại các cơ sở y tế (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chi phí chụp MRI sọ não tại bệnh viện công lập và tư nhân hiện nay khoảng bao nhiêu tiền? BHYT chi trả như thế nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khi có chỉ định nhập viện phẫu thuật u não, gia đình và người bệnh cần chuẩn bị thủ tục hành chính và tài chính tạm ứng ra sao?', 'Gia đình cần chuẩn bị chu đáo: (1) Giấy tờ tùy thân bản gốc và bản photocopy (CCCD, thẻ BHYT, giấy chuyển tuyến); (2) Tiền tạm ứng viện phí (thường khoảng 10 - 30 triệu đồng tại bệnh viện công tùy danh mục BHYT, hoặc cao hơn tại khu vực dịch vụ theo yêu cầu); (3) Cắt cử ít nhất 1-2 người nhà khỏe mạnh, tâm lý vững vàng để túc trực ký cam kết phẫu thuật và chăm sóc hậu phẫu; (4) Chuẩn bị đồ dùng cá nhân gọn nhẹ (khăn mềm, bỉm người lớn, quần áo rộng cài cúc phía trước, ly có ống hút mềm).', 'Bệnh viện Hữu nghị Việt Đức & Bệnh viện Chợ Rẫy — Hướng dẫn người bệnh và thân nhân làm thủ tục nhập viện phẫu thuật thần kinh (https://benhvienvietduc.org)', 'faq_visit_guide'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khi có chỉ định nhập viện phẫu thuật u não, gia đình và người bệnh cần chuẩn bị thủ tục hành chính và tài chính tạm ứng ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Yếu tố nguy cơ nào đối với bệnh u não hiện nay đã được y học xác nhận bằng chứng khoa học rõ ràng nhất?', 'Theo Tổ chức Y tế Thế giới (WHO) và Viện Ung thư Quốc gia Hoa Kỳ (NCI), yếu tố nguy cơ từ môi trường duy nhất được chứng minh rõ ràng làm tăng nguy cơ mắc u não là TIẾP XÚC VỚI BỨC XẠ ION HÓA (Ionizing Radiation). Các trường hợp này bao gồm: người từng phải xạ trị vùng đầu cổ khi còn nhỏ để điều trị các bệnh lý ung thư khác, hoặc người phơi nhiễm phóng xạ năng lượng cao trong các tai nạn hạt nhân. Ngược lại, bức xạ thông thường trong y tế như chụp X-quang hoặc CT scan ngực bụng chỉ sử dụng liều xạ rất thấp nằm trong ngưỡng kiểm soát an toàn nghiêm ngặt.', 'National Cancer Institute (NCI) & WHO — Các yếu tố nguy cơ gây u não và tủy sống được xác nhận bằng chứng khoa học (https://www.cancer.gov)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Yếu tố nguy cơ nào đối với bệnh u não hiện nay đã được y học xác nhận bằng chứng khoa học rõ ràng nhất?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bệnh u não có tính chất di truyền trong gia đình không? Những hội chứng gen hiếm gặp nào làm tăng nguy cơ mắc bệnh?', 'Đại đa số các ca u não (trên 95%) xuất hiện đơn lẻ, tự phát và KHÔNG di truyền trực tiếp từ cha mẹ sang con cái. Chỉ dưới 5% trường hợp liên quan đến các HỘI CHỨNG DI TRUYỀN HIẾM GẶP do đột biến gen di truyền mầm lặn/trội, tiêu biểu gồm: (1) Hội chứng u sợi thần kinh Type 1 và Type 2 (NF1, NF2 - tăng nguy cơ u thần kinh thính giác, u màng não, u thần kinh đệm); (2) Hội chứng Li-Fraumeni (đột biến gen TP53); (3) Hội chứng Von Hippel-Lindau (VHL - u nguyên bào mạch máu); (4) Hội chứng xơ cứng củ (Tuberous Sclerosis) và hội chứng Turcot.', 'American Cancer Society (ACS) & Vinmec — Yếu tố di truyền và các hội chứng gen gia đình liên quan đến u thần kinh trung ương (https://www.cancer.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bệnh u não có tính chất di truyền trong gia đình không? Những hội chứng gen hiếm gặp nào làm tăng nguy cơ mắc bệnh?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thói quen nghe điện thoại di động áp sát tai nhiều năm có gây ra u não không? Các nghiên cứu của WHO và NCI nói gì?', 'Sóng điện thoại di động là BỨC XẠ KHÔNG ION HÓA (tần số vô tuyến RF-EMF), mức năng lượng thấp này không đủ để phá vỡ liên kết hóa học hay gây đứt gãy trực tiếp DNA như tia X hay tia Gamma. Các nghiên cứu dịch tễ học quốc tế quy mô lớn của WHO (như nghiên cứu INTERPHONE trên hàng chục nghìn người) và Viện Ung thư Quốc gia Mỹ (NCI) đều kết luận: Cho đến nay CHƯA CÓ BẰNG CHỨNG KHOA HỌC XÁC THỰC chứng minh việc dùng điện thoại di động làm tăng tỷ lệ mắc u não. Dù vậy, các chuyên gia vẫn khuyến cáo nên sử dụng tai nghe, loa ngoài hoặc nhắn tin khi có thể để hạn chế tối đa việc áp sát thiết bị vào đầu trong thời gian dài.', 'World Health Organization (WHO) & NCI — Điện từ trường và sức khỏe cộng đồng: Nghiên cứu về điện thoại di động và nguy cơ u não (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thói quen nghe điện thoại di động áp sát tai nhiều năm có gây ra u não không? Các nghiên cứu của WHO và NCI nói gì?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tuổi tác và giới tính ảnh hưởng như thế nào đến tỷ lệ mắc các loại u não khác nhau?', 'Nguy cơ mắc u não thay đổi theo độ tuổi và giới tính: (1) Theo tuổi: Mặc dù u não có thể gặp ở mọi lứa tuổi, nhưng nhìn chung nguy cơ mắc u não tăng dần theo độ tuổi, phổ biến nhất ở người từ 50-70 tuổi (đặc biệt u thần kinh đệm Glioblastoma); tuy nhiên một số loại u tế bào mầm và u nguyên bào tủy lại hay gặp ở trẻ em; (2) Theo giới tính: U thần kinh đệm (Glioma) gặp ở nam giới nhiều hơn nữ giới, trong khi U màng não (Meningioma) lại có tỷ lệ mắc ở phụ nữ cao gấp hơn 2 lần nam giới do liên quan mật thiết đến các thụ thể nội tiết tố nữ (Estrogen và Progesterone).', 'American Brain Tumor Association (ABTA) & Mayo Clinic — Dịch tễ học và đặc điểm phân bố theo lứa tuổi, giới tính của các khối u sọ não (https://www.mayoclinic.org/diseases-conditions/glioma/symptoms-causes/syc-20350251)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tuổi tác và giới tính ảnh hưởng như thế nào đến tỷ lệ mắc các loại u não khác nhau?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Từng bị va đập đầu, té ngã chấn thương sọ não hoặc tai nạn giao thông trong quá khứ có phải là nguyên nhân sinh ra u não không?', 'Theo Mayo Clinic và Hiệp hội Ung thư Hoa Kỳ, đây là một HIỂU LẦM RẤT PHỔ BIẾN. Các nghiên cứu khoa học kiểm soát nghiêm ngặt khẳng định chấn thương đầu KHÔNG PHẢI là nguyên nhân gây ra khối u não. Hiện tượng mọi người thường liên hệ tai nạn với u não là do ''sai lệch nhớ lại'' (Recall Bias): Sau khi bị va đập đầu, bệnh nhân xuất hiện triệu chứng đau đầu và được chỉ định chụp CT/MRI, từ đó tình cờ phát hiện ra khối u đã âm thầm tồn tại từ trước mà người bệnh không hề hay biết.', 'Mayo Clinic & American Cancer Society — Giải mã các hiểu lầm phổ biến: Chấn thương đầu và nguy cơ phát triển u não (https://www.mayoclinic.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Từng bị va đập đầu, té ngã chấn thương sọ não hoặc tai nạn giao thông trong quá khứ có phải là nguyên nhân sinh ra u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người có hệ miễn dịch bị suy giảm nặng (HIV/AIDS, người ghép tạng dùng thuốc ức chế miễn dịch) có nguy cơ mắc loại u não nào?', 'Người bệnh có hệ miễn dịch suy giảm nặng có nguy cơ cao rõ rệt mắc U LYMPHO HỆ THẦN KINH TRUNG ƯƠNG NGUYÊN PHÁT (Primary Central Nervous System Lymphoma - PCNSL). Ở những bệnh nhân này, cơ chế giám sát miễn dịch của cơ thể bị suy yếu, tạo điều kiện cho virus Epstein-Barr (EBV) tái kích hoạt làm biến đổi ác tính các tế bào lympho B trong nhu mô não. Việc điều trị kiểm soát tốt tải lượng virus HIV bằng thuốc ARV giúp giảm đáng kể nguy cơ phát triển loại u này.', 'Bệnh viện Bạch Mai & Johns Hopkins Medicine — Mối liên quan giữa suy giảm miễn dịch và u lympho hệ thần kinh trung ương nguyên phát (https://bachmai.gov.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người có hệ miễn dịch bị suy giảm nặng (HIV/AIDS, người ghép tạng dùng thuốc ức chế miễn dịch) có nguy cơ mắc loại u não nào?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tiếp xúc nghề nghiệp với hóa chất công nghiệp nào bị nghi ngờ liên quan đến u não và người lao động cần phòng ngừa ra sao?', 'Một số nghiên cứu dịch tễ học quan sát thấy tỷ lệ mắc u não cao hơn ở công nhân làm việc trong ngành lọc hóa dầu, sản xuất cao su tổng hợp hoặc tiếp xúc thường xuyên với thuốc trừ sâu công nghiệp và dung môi hữu cơ (như Vinyl Chloride). Tuy nhiên, bằng chứng trực tiếp xác lập quan hệ nhân quả vẫn chưa hoàn toàn thống nhất. Dù vậy, theo tiêu chuẩn an toàn lao động của Bộ Y tế, công nhân trong các môi trường này bắt buộc phải trang bị đồ bảo hộ chuyên dụng (mặt nạ lọc khí, găng tay chống hóa chất) và khám sức khỏe định kỳ.', 'Bộ Y tế Việt Nam & Viện Sức khỏe nghề nghiệp và Môi trường — Hướng dẫn bảo hộ lao động và phòng ngừa phơi nhiễm hóa chất độc hại trong môi trường công nghiệp (https://moh.gov.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tiếp xúc nghề nghiệp với hóa chất công nghiệp nào bị nghi ngờ liên quan đến u não và người lao động cần phòng ngừa ra sao?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Lối sống lành mạnh và chế độ ăn uống khoa học có vai trò thực tế như thế nào trong việc bảo vệ sức khỏe não bộ?', 'Theo Duke University và Vinmec, duy trì lối sống lành mạnh (dinh dưỡng cân đối, vận động thể lực, kiểm soát căng thẳng và ngủ đủ giấc) đóng vai trò nền tảng giúp: (1) Tăng cường hệ miễn dịch tự nhiên giúp nhận diện và tiêu diệt các tế bào bất thường; (2) Giảm các phản ứng viêm mạn tính và giảm tổn thương oxy hóa do các gốc tự do tác động lên tế bào thần kinh; (3) Cải thiện tuần hoàn máu não và duy trì hàng rào máu não khỏe mạnh. Lối sống lành mạnh là chìa khóa nâng cao thể trạng tổng thể nhưng không phải là bảo chứng tuyệt đối ngăn ngừa hoàn toàn u não.', 'Tisch Brain Tumor Center - Duke University & Vinmec — Vai trò của lối sống và dinh dưỡng đối với sức khỏe hệ thần kinh trung ương (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Lối sống lành mạnh và chế độ ăn uống khoa học có vai trò thực tế như thế nào trong việc bảo vệ sức khỏe não bộ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Có chế độ ăn kiêng, thực dưỡng hoặc thực phẩm chức năng nào có thể cam kết ''ngăn ngừa 100% u não'' không?', 'TUYỆT ĐỐI KHÔNG CÓ bất kỳ chế độ ăn, phương pháp thực dưỡng hay loại thực phẩm chức năng nào có thể khẳng định ngăn ngừa được 100% mọi trường hợp u não. Y học hiện đại khẳng định: Khối u não phát sinh chủ yếu do các đột biến gen ngẫu nhiên (Somatic Mutations) tích tụ trong quá trình sao chép DNA của tế bào thần kinh đệm hoặc màng não mà cơ thể không thể kiểm soát hoàn toàn. Người dân cần hết sức cảnh giác trước các chiêu trò quảng cáo thổi phồng về ''chế độ ăn tiêu diệt mầm mống u'' hay ''thần dược phòng ngừa ung thư não'' để tránh tiền mất tật mang.', 'Bệnh viện K Trung ương & Vinmec — Cảnh báo các hiểu lầm và tuyên bố sai lệch về chế độ ăn ngăn ngừa ung thư (https://benhvienk.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Có chế độ ăn kiêng, thực dưỡng hoặc thực phẩm chức năng nào có thể cam kết ''ngăn ngừa 100% u não'' không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thói quen ăn nhiều thịt chế biến sẵn chứa nitrit/nitrat (xúc xích, thịt xông khói, dưa muối khú) ảnh hưởng thế nào đến cơ thể?', 'Theo Tổ chức Y tế Thế giới (IARC/WHO), thịt chế biến sẵn (như xúc xích, lạp xưởng, giăm bông, thịt muối) chứa muối nitrit/nitrat được sử dụng để bảo quản. Khi vào đường tiêu hóa và gặp môi trường acid dạ dày, các chất này có thể chuyển hóa thành hợp chất N-Nitroso (NOCs) - một nhóm chất có khả năng sinh ung thư và đã được ghi nhận trong các nghiên cứu trên động vật về tổn hại DNA tế bào. Chuyên gia dinh dưỡng khuyến cáo cộng đồng nên hạn chế tối đa các thực phẩm này và thay thế bằng thịt tươi sống, cá và đạm thực vật.', 'World Health Organization (WHO) - IARC — Đánh giá mức độ an toàn và nguy cơ sinh ung thư của thịt chế biến sẵn chứa hợp chất Nitroso (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thói quen ăn nhiều thịt chế biến sẵn chứa nitrit/nitrat (xúc xích, thịt xông khói, dưa muối khú) ảnh hưởng thế nào đến cơ thể?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chế độ ăn Địa Trung Hải và các thực phẩm giàu chất chống oxy hóa mang lại lợi ích gì cho tế bào não bộ?', 'Chế độ ăn Địa Trung Hải (Mediterranean Diet) được các nhà thần kinh học đánh giá rất cao cho sức khỏe não: (1) Giàu chất chống oxy hóa Polyphenol và Flavonoid từ rau xanh đậm (cải bó xôi, súp lơ), quả mọng (việt quất, dâu tây) giúp trung hòa gốc tự do bảo vệ màng tế bào thần kinh; (2) Cung cấp acid béo Omega-3 (DHA và EPA) dồi dào từ các loại cá béo (cá hồi, cá thu) và hạt óc chó giúp duy trì tính toàn vẹn cấu trúc bao myelin và giảm phản ứng viêm thần kinh; (3) Sử dụng dầu ô liu nguyên chất cung cấp chất béo không bão hòa đơn có lợi cho vi tuần hoàn não.', 'Cleveland Clinic & Harvard T.H. Chan School of Public Health — Lợi ích của chế độ ăn Địa Trung Hải đối với bảo vệ và chống lão hóa tế bào thần kinh (https://my.clevelandclinic.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chế độ ăn Địa Trung Hải và các thực phẩm giàu chất chống oxy hóa mang lại lợi ích gì cho tế bào não bộ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Giấc ngủ sâu và đồng hồ sinh học có vai trò gì trong việc ''dọn dẹp độc tố'' và duy trì sức khỏe của não bộ?', 'Khoa học thần kinh đã phát hiện HỆ THỐNG GLYMPHATIC (hệ thống dọn rác sinh học của não): Trong giai đoạn giấc ngủ sâu (sóng chậm), các tế bào thần kinh đệm sẽ co lại, làm gia tăng khoảng gian bào giúp dòng dịch não tủy lưu thông mạnh mẽ gấp 10-20 lần so với lúc thức, cuốn trôi các chất cặn bã, gốc tự do và protein bất thường tích tụ trong ngày. Ngược lại, mất ngủ mạn tính hoặc thức khuya triền miên làm ngưng trệ quá trình tự làm sạch này, dẫn đến tích tụ stress oxy hóa và đẩy nhanh quá trình lão hóa, suy thoái tế bào não.', 'National Institutes of Health (NIH) & Vinmec — Khám phá hệ thống Glymphatic và vai trò của giấc ngủ trong đào thải độc tố não bộ (https://www.vinmec.com)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Giấc ngủ sâu và đồng hồ sinh học có vai trò gì trong việc ''dọn dẹp độc tố'' và duy trì sức khỏe của não bộ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Hút thuốc lá và lạm dụng rượu bia có trực tiếp gây ra u não nguyên phát không, và ảnh hưởng ra sao đến điều trị?', 'Mặc dù thuốc lá không được coi là nguyên nhân trực tiếp gây ra u não nguyên phát (như Glioma hay Meningioma), nhưng hút thuốc lá là nguyên nhân số 1 gây UNG THƯ PHỔI DI CĂN LÊN NÃO (loại u não thứ phát nguy hiểm và phổ biến nhất ở người lớn tuổi). Ngoài ra, nicotine và cồn làm tổn hại hàng rào máu não, gây xơ vữa hẹp mạch máu nuôi não, làm giảm lượng oxy cung cấp cho mô não lành và làm tăng đáng kể nguy cơ biến chứng nhiễm trùng hoặc chảy máu khi phải trải qua phẫu thuật sọ não.', 'American Cancer Society & Bệnh viện K — Tác hại của thuốc lá và rượu bia đối với nguy cơ ung thư di căn não và kết quả điều trị (https://benhvienk.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Hút thuốc lá và lạm dụng rượu bia có trực tiếp gây ra u não nguyên phát không, và ảnh hưởng ra sao đến điều trị?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Căng thẳng tinh thần kéo dài (stress mạn tính) có phải là nguyên nhân trực tiếp kích hoạt tế bào u não không?', 'Stress tâm lý kéo dài KHÔNG PHẢI là nguyên nhân trực tiếp làm đột biến gen để biến tế bào lành thành tế bào u não. Tuy nhiên, tình trạng stress mạn tính kích thích cơ thể giải phóng liên tục các hormone căng thẳng (như Cortisol và Adrenaline), gây ức chế hoạt động của các tế bào miễn dịch tự nhiên (tế bào NK, tế bào T) - những tế bào có nhiệm vụ phát hiện và tiêu diệt sớm các mầm mống bất thường. Do đó, kiểm soát căng thẳng bằng thiền, yoga, đi bộ và giữ tinh thần lạc quan là liệu pháp hỗ trợ bảo vệ sức khỏe rất quan trọng.', 'Mayo Clinic & Bệnh viện Đa khoa Tâm Anh — Mối tương tác giữa căng thẳng tâm lý, hệ miễn dịch và bệnh lý ung bướu (https://tamanhhospital.vn/tin-tuc/u-nao-chan-doan-dieu-tri-hieu-qua-bang-phuong-phap-hien-dai/)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Căng thẳng tinh thần kéo dài (stress mạn tính) có phải là nguyên nhân trực tiếp kích hoạt tế bào u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Người hoàn toàn khỏe mạnh, không có triệu chứng bất thường có nên tự ý đi chụp MRI định kỳ để ''tầm soát u não'' không?', 'Các hiệp hội thần kinh và chẩn đoán hình ảnh quốc tế KHÔNG KHUYẾN CÁO người khỏe mạnh bình thường tự ý chụp MRI sọ não đại trà để tầm soát. Lý do: (1) Tỷ lệ mắc u não nguyên phát trong dân số chung là rất thấp (chỉ khoảng 5-10 ca trên 100.000 dân); (2) Chụp MRI đại trà dễ phát hiện các tổn thương ngẫu nhiên vô hại (như u nang màng nhện nhỏ, tổn thương chất trắng lành tính do tuổi tác), gây ra tâm lý hoang mang, lo lắng thái quá và dẫn đến các can thiệp y tế quá mức không cần thiết. Chụp MRI chỉ thực sự cần thiết khi có triệu chứng lâm sàng cảnh báo hoặc thuộc nhóm gia đình có hội chứng di truyền nguy cơ cao.', 'American College of Radiology (ACR) & Vinmec — Khuyến cáo y khoa về việc tầm soát chẩn đoán hình ảnh sọ não ở người không triệu chứng (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Người hoàn toàn khỏe mạnh, không có triệu chứng bất thường có nên tự ý đi chụp MRI định kỳ để ''tầm soát u não'' không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Khi nào thì các thành viên trong gia đình của bệnh nhân u não nên đi khám tư vấn di truyền và tầm soát định kỳ?', 'Việc khám tư vấn di truyền và tầm soát chỉ được chỉ định khi gia đình có các dấu hiệu nguy cơ gen đặc biệt: (1) Gia đình có từ 2 người thân bậc 1 (cha mẹ, anh chị em ruột, con cái) cùng mắc u não hoặc ung thư ở độ tuổi trẻ (dưới 40 tuổi); (2) Bệnh nhân đã được chẩn đoán mắc các hội chứng di truyền đã biết như NF1, NF2, Li-Fraumeni, VHL; (3) Xuất hiện các dấu hiệu gợi ý hội chứng gen trên da như nhiều đốm cà phê sữa (Café-au-lait spots), u xơ mềm dưới da hoặc nốt tàn nhang ở nách bẹn. Khi đó, gia đình nên đến trung tâm y học di truyền để làm xét nghiệm giải trình tự gen và lập kế hoạch theo dõi định kỳ chuyên biệt.', 'Bệnh viện Hữu nghị Việt Đức & Johns Hopkins Medicine — Chỉ định tư vấn di truyền và theo dõi tầm soát cho các gia đình có nguy cơ u thần kinh cao (https://benhvienvietduc.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Khi nào thì các thành viên trong gia đình của bệnh nhân u não nên đi khám tư vấn di truyền và tầm soát định kỳ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Sóng Wifi, tai nghe Bluetooth không dây (như AirPods) hay lò vi sóng trong nhà có phát ra bức xạ gây u não không?', 'Theo WHO và FDA Hoa Kỳ, sóng Wifi, Bluetooth và lò vi sóng đều sử dụng sóng vô tuyến tần số thấp (Non-ionizing RF radiation) với công suất phát cực kỳ yếu (tai nghe Bluetooth phát sóng yếu hơn điện thoại di động hàng chục lần). Lò vi sóng được bọc lồng kim loại kín ngăn rò rỉ sóng ra ngoài. Hàng trăm nghiên cứu độc lập đã chứng minh các thiết bị gia dụng này hoàn toàn an toàn khi sử dụng đúng cách, không có đủ năng lượng để gây biến đổi DNA hay kích hoạt tế bào u não.', 'World Health Organization (WHO) & FDA Hoa Kỳ — Đánh giá an toàn bức xạ của các thiết bị không dây và gia dụng đối với sức khỏe (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Sóng Wifi, tai nghe Bluetooth không dây (như AirPods) hay lò vi sóng trong nhà có phát ra bức xạ gây u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chụp X-quang răng định kỳ hoặc từng chụp CT scan lồng ngực/bụng nhiều lần có làm tăng nguy cơ bị u não không?', 'Theo Hiệp hội Điện quang Hoa Kỳ (ACR) và Vinmec, chụp X-quang nha khoa chỉ sử dụng liều bức xạ siêu nhỏ (tương đương vài ngày phơi nhiễm bức xạ tự nhiên từ môi trường) và người bệnh luôn được đeo yếm chì bảo vệ vùng cổ, do đó không làm tăng nguy cơ u não. Đối với chụp CT scan toàn thân, ngành y tế luôn tuân thủ nghiêm ngặt nguyên tắc ALARA (As Low As Reasonably Achievable - liều xạ thấp nhất có thể) và chỉ chỉ định khi lợi ích chẩn đoán vượt trội rủi ro; liều tích lũy từ các lần chụp thông thường không đủ để kích hoạt u não.', 'American College of Radiology (ACR) & Vinmec — An toàn bức xạ trong chẩn đoán hình ảnh y khoa và nguyên tắc ALARA (https://www.vinmec.com/vie/bai-viet/trieu-chung-canh-bao-u-nao-cach-dieu-tri-vi)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chụp X-quang răng định kỳ hoặc từng chụp CT scan lồng ngực/bụng nhiều lần có làm tăng nguy cơ bị u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Thường xuyên nhuộm tóc, ép uốn tóc bằng hóa chất mỹ phẩm có làm tăng nguy cơ u màng não hay u thần kinh đệm không?', 'Theo Viện Ung thư Quốc gia Hoa Kỳ (NCI) và Mayo Clinic, các nghiên cứu dịch tễ học kiểm chứng quy mô lớn ở những người dùng thuốc nhuộm tóc cá nhân cũng như các thợ làm tóc chuyên nghiệp cho thấy KHÔNG CÓ BẰNG CHỨNG thuyết phục nào liên kết việc dùng thuốc nhuộm tóc hiện đại với sự gia tăng nguy cơ mắc u não. Các công thức thuốc nhuộm ngày nay đã loại bỏ nhiều amin thơm độc hại trước thập niên 1980. Dù vậy, chuyên gia khuyến cáo nên thao tác nơi thoáng khí, dùng găng tay và không để hóa chất tiếp xúc da đầu khi đang có vết trầy xước.', 'National Cancer Institute (NCI) & Mayo Clinic — Nghiên cứu về thuốc nhuộm tóc và nguy cơ ung thư hệ thần kinh (https://www.cancer.gov)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Thường xuyên nhuộm tóc, ép uốn tóc bằng hóa chất mỹ phẩm có làm tăng nguy cơ u màng não hay u thần kinh đệm không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chất làm ngọt nhân tạo Aspartame trong nước ngọt ăn kiêng có gây u não như những tin đồn lan truyền trên mạng xã hội không?', 'Theo Cơ quan Quản lý Thực phẩm và Dược phẩm Hoa Kỳ (FDA) và Viện Ung thư Quốc gia Mỹ (NCI), tin đồn Aspartame gây u não xuất phát từ một thí nghiệm trên chuột từ thập niên 1970 với phương pháp nghiên cứu có nhiều sai sót. Hàng loạt nghiên cứu dịch tễ học sâu rộng trên con người sau đó đã theo dõi hàng trăm nghìn đối tượng và kết luận: Sử dụng Aspartame trong ngưỡng cho phép hàng ngày (ADI) hoàn toàn an toàn và KHÔNG liên quan đến nguy cơ mắc u não hay ung thư thần kinh.', 'U.S. FDA & National Cancer Institute (NCI) — Đánh giá an toàn thực phẩm của chất tạo ngọt nhân tạo Aspartame và nguy cơ u não (https://www.fda.gov)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chất làm ngọt nhân tạo Aspartame trong nước ngọt ăn kiêng có gây u não như những tin đồn lan truyền trên mạng xã hội không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Chế độ ăn Keto (Ketogenic - cắt giảm hoàn toàn tinh bột, ăn nhiều chất béo) có thể ''bỏ đói'' và tiêu diệt khối u não được không?', 'Theo Mayo Clinic và Bệnh viện K, quan niệm ''cắt giảm đường để bỏ đói tế bào u não'' là một SAI LẦM NGUY HIỂM. Mặc dù tế bào não tiêu thụ glucose, nhưng khi cơ thể thiếu carbohydrate, gan sẽ chuyển đổi mỡ thành thể ketone và một số tế bào u não vẫn có thể thích nghi chuyển hóa năng lượng từ mỡ hoặc acid amin (như Glutamine). Tự ý ăn Keto cực đoan khiến người bệnh suy kiệt thể trạng, sụt cân nghiêm trọng, mất cơ bắp và giảm bạch cầu, dẫn đến không đủ sức khỏe để đáp ứng phác đồ hóa - xạ trị chuẩn y khoa.', 'Mayo Clinic & Bệnh viện K Trung ương — Sự thật về chế độ ăn Ketogenic và hiểu lầm bỏ đói tế bào khối u não (https://benhvienk.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Chế độ ăn Keto (Ketogenic - cắt giảm hoàn toàn tinh bột, ăn nhiều chất béo) có thể ''bỏ đói'' và tiêu diệt khối u não được không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Ăn nhiều đường ngọt có trực tiếp ''nuôi'' tế bào u não phát triển nhanh hơn không?', 'Theo Hiệp hội Ung thư Hoa Kỳ (ACS) và Vinmec, mọi tế bào sống trong cơ thể người (cả tế bào lành lẫn tế bào u) đều cần glucose làm nhiên liệu chuyển hóa. Việc ăn đường ngọt KHÔNG trực tiếp làm khối u phát triển nhanh hơn một cách đặc hiệu, và việc kiêng tuyệt đối đường cũng không làm khối u biến mất. Tuy nhiên, ăn quá nhiều đường tinh luyện làm tăng nguy cơ béo phì, kháng insulin và gây phản ứng viêm mạn tính trong cơ thể - những yếu tố gián tiếp làm suy yếu hệ miễn dịch. Khuyến nghị duy trì chế độ ăn cân bằng dinh dưỡng, hạn chế đồ uống có đường.', 'American Cancer Society & Vinmec — Mối liên hệ giữa tiêu thụ đường, chuyển hóa năng lượng và bệnh ung bướu (https://www.cancer.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Ăn nhiều đường ngọt có trực tiếp ''nuôi'' tế bào u não phát triển nhanh hơn không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Uống cà phê hoặc trà xanh mỗi ngày có tác động như thế nào đến sức khỏe não bộ và nguy cơ u não?', 'Theo các nghiên cứu dịch tễ học đăng tải trên tạp chí Thần kinh học Hoa Kỳ và Harvard Health: Uống 1-2 tách cà phê hoặc trà xanh nguyên chất mỗi ngày chứa hàm lượng lớn chất chống oxy hóa Polyphenol, Chlorogenic Acid và EGCG. Các hợp chất này giúp bảo vệ tế bào thần kinh khỏi stress oxy hóa, tăng độ nhạy insulin và một số phân tích gộp thậm chí ghi nhận tỷ lệ u thần kinh đệm (Glioma) thấp hơn nhẹ ở người có thói quen uống trà/cà phê điều độ. Tuy nhiên, không nên uống quá nhiều vào buổi tối gây mất ngủ.', 'Harvard T.H. Chan School of Public Health & ABTA — Tác động của cà phê và trà xanh đối với sức khỏe hệ thần kinh và nguy cơ khối u sọ não (https://www.hsph.harvard.edu)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Uống cà phê hoặc trà xanh mỗi ngày có tác động như thế nào đến sức khỏe não bộ và nguy cơ u não?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Phụ nữ dùng thuốc tránh thai hoặc liệu pháp hormone thay thế (HRT) kéo dài có làm tăng nguy cơ mắc U màng não (Meningioma) không?', 'Theo Johns Hopkins Medicine và ANSM (Cơ quan Dược phẩm Pháp), tế bào u màng não thường có nhiều thụ thể Progesterone và Estrogen. Sử dụng liều cao kéo dài các loại thuốc chứa Progestin tổng hợp mạnh (như Cyproterone acetate, Chlormadinone acetate) có liên quan đến việc tăng nguy cơ hình thành hoặc phát triển kích thước u màng não. Đối với thuốc tránh thai liều thấp thông thường hoặc liệu pháp HRT ngắn hạn, nguy cơ này là rất thấp. Phụ nữ có tiền sử u màng não cần tham vấn kỹ bác sĩ Sản khoa và Thần kinh trước khi dùng hormone.', 'Johns Hopkins Medicine & ANSM (Pháp) — Nguy cơ u màng não liên quan đến việc sử dụng các thuốc progestin liều cao kéo dài (https://www.hopkinsmedicine.org/health/conditions-and-diseases/meningioma)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Phụ nữ dùng thuốc tránh thai hoặc liệu pháp hormone thay thế (HRT) kéo dài có làm tăng nguy cơ mắc U màng não (Meningioma) không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Uống bổ sung các viên vitamin tổng hợp (Vitamin D, E, C, Coenzyme Q10) có giúp phòng ngừa u não không?', 'Theo Mayo Clinic và Cleveland Clinic, hiện CHƯA CÓ THỬ NGHIỆM LÂM SÀNG NÀO chứng minh việc uống bổ sung liều cao các loại vitamin tổng hợp hoặc thực phẩm chức năng có thể ngăn ngừa u não ở người bình thường. Thậm chí, việc lạm dụng quá liều một số chất chống oxy hóa dạng viên uống (như Vitamin E, Vitamin A liều cao) có thể gây tác dụng ngược hoặc can thiệp tiêu cực vào hiệu quả của xạ trị và hóa trị. Nguồn vi chất và vitamin tốt nhất cho não bộ vẫn là từ thực phẩm tươi tự nhiên (rau xanh, trái cây, cá béo, hạt ngũ cốc nguyên cám).', 'Mayo Clinic & Cleveland Clinic — Đánh giá hiệu quả của viên uống vitamin bổ sung trong phòng ngừa ung bướu thần kinh (https://my.clevelandclinic.org)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Uống bổ sung các viên vitamin tổng hợp (Vitamin D, E, C, Coenzyme Q10) có giúp phòng ngừa u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Bụi mịn không khí (PM2.5) và khói xả xe cộ đô thị có xâm nhập vào não và làm tăng nguy cơ u thần kinh không?', 'Các hạt bụi siêu mịn PM2.5 và hạt nano siêu nhỏ trong không khí ô nhiễm có khả năng đi qua niêm mạc mũi theo dây thần kinh khứu giác hoặc thẩm thấu qua phế nang vào máu để vượt qua hàng rào máu não. Nghiên cứu dịch tễ học quốc tế chỉ ra ô nhiễm không khí làm gia tăng các phản ứng viêm thần kinh và stress oxy hóa mô não, liên quan đến nguy cơ suy giảm nhận thức và đột quỵ; mối liên hệ với u não đang tiếp tục được nghiên cứu sâu hơn. Các chuyên gia khuyến nghị đeo khẩu trang lọc bụi chuẩn N95/KN95 khi ra đường và dùng máy lọc không khí trong nhà.', 'World Health Organization (WHO) & Bệnh viện Đa khoa Tâm Anh — Tác động của ô nhiễm không khí và hạt bụi mịn PM2.5 lên hệ thần kinh trung ương (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Bụi mịn không khí (PM2.5) và khói xả xe cộ đô thị có xâm nhập vào não và làm tăng nguy cơ u thần kinh không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tập thể dục nhịp điệu (chạy bộ, đạp xe, bơi lội) tác động như thế nào đến não bộ và khả năng chống lại bệnh tật?', 'Theo Harvard Medical School, tập thể dục nhịp điệu kích thích não bộ tiết ra yếu tố dinh dưỡng thần kinh BDNF (Brain-Derived Neurotrophic Factor) - một protein thúc đẩy sự sống còn, sửa chữa và tái sinh tế bào thần kinh (Neurogenesis). Vận động thể chất ít nhất 150 phút/tuần giúp kiểm soát huyết áp, tối ưu hóa lưu lượng máu lên não, giảm tình trạng viêm toàn thân và tăng cường khả năng tuần tra của các tế bào miễn dịch (T-cells và NK-cells) trong việc tiêu diệt các tế bào đột biến.', 'Harvard Medical School & Vinmec — Lợi ích của hoạt động thể lực đối với quá trình sinh thần kinh và tăng cường miễn dịch não (https://www.health.harvard.edu)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tập thể dục nhịp điệu (chạy bộ, đạp xe, bơi lội) tác động như thế nào đến não bộ và khả năng chống lại bệnh tật?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Làm việc ca đêm triền miên (Night Shift) làm đảo lộn đồng hồ sinh học có ảnh hưởng gì đến nguy cơ ung bướu?', 'Theo Cơ quan Nghiên cứu Ung thư Quốc tế (IARC/WHO), làm việc ca đêm làm gián đoạn nhịp sinh học ngày đêm (Circadian Rhythm) và ức chế quá trình tổng hợp Melatonin - hormone tự nhiên do tuyến tùng tiết ra trong bóng tối ban đêm. Melatonin là chất chống oxy hóa nội sinh mạnh mẽ có vai trò ức chế các gốc tự do và điều hòa quá trình chết theo chương trình của tế bào (Apoptosis). Người làm việc ca đêm cần ngủ bù trong phòng tối hoàn toàn, giữ chu kỳ ngủ ổn định và hạn chế ánh sáng xanh ban đêm.', 'IARC - World Health Organization (WHO) — Đánh giá của IARC về sự gián đoạn nhịp sinh học do làm việc theo ca và nguy cơ ung bướu (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Làm việc ca đêm triền miên (Night Shift) làm đảo lộn đồng hồ sinh học có ảnh hưởng gì đến nguy cơ ung bướu?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tại sao một số nghiên cứu dịch tễ học lại ghi nhận người có cơ địa dị ứng (hen suyễn, viêm mũi dị ứng) có tỷ lệ u thần kinh đệm thấp hơn?', 'Đây là một phát hiện dịch tễ học rất đáng chú ý được công bố bởi Viện Ung thư Quốc gia Mỹ (NCI) và Đại học Oxford: Các phân tích gộp lớn cho thấy người có tiền sử bệnh dị ứng (như viêm da atopy, sốt cỏ khô, hen suyễn) có tỷ lệ mắc U thần kinh đệm (Glioma) thấp hơn khoảng 20-30% so với người bình thường. Giả thuyết y khoa cho rằng: Hệ miễn dịch của người cơ địa dị ứng ở trạng thái hoạt hóa tăng động (Hyperactive Immune Surveillance), từ đó tăng cường khả năng phát hiện sớm và tiêu diệt các tế bào tiền u não ngay từ giai đoạn đột biến ban đầu.', 'National Cancer Institute (NCI) & Oxford University — Mối liên quan nghịch đảo giữa bệnh lý dị ứng và nguy cơ mắc u thần kinh đệm ở người (https://www.cancer.gov)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tại sao một số nghiên cứu dịch tễ học lại ghi nhận người có cơ địa dị ứng (hen suyễn, viêm mũi dị ứng) có tỷ lệ u thần kinh đệm thấp hơn?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Các gói khám sức khỏe tổng quát định kỳ hàng năm có phát hiện sớm được u não không?', 'Hầu hết các gói khám sức khỏe tổng quát thông thường (chỉ bao gồm xét nghiệm máu cơ bản, chụp X-quang phổi và siêu âm bụng) KHÔNG THỂ phát hiện được u não ở giai đoạn sớm khi chưa có triệu chứng. Để phát hiện u não, bắt buộc phải chụp cắt lớp vi tính (CT) hoặc cộng hưởng từ (MRI) sọ não. Tuy nhiên, khám tổng quát giúp phát hiện sớm các bệnh lý nền nguy cơ (như tiểu đường, cao huyết áp, ung thư tạng khác di căn lên não) và bác sĩ lâm sàng có thể phát hiện các triệu chứng thần kinh bất thường sớm để chỉ định chụp MRI kịp thời.', 'Bệnh viện Bạch Mai & Vinmec — Giới hạn của các gói khám sức khỏe tổng quát trong phát hiện sớm khối u nội sọ (https://bachmai.gov.vn)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Các gói khám sức khỏe tổng quát định kỳ hàng năm có phát hiện sớm được u não không?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Nước uống nhiễm kim loại nặng (chì, asen, thủy ngân) hoặc vi nhựa (microplastics) có liên quan gì đến tổn thương não bộ?', 'Theo WHO và Viện Khoa học Sức khỏe Môi trường Quốc gia Hoa Kỳ (NIEHS), kim loại nặng (đặc biệt là chì và thủy ngân) là những chất độc thần kinh (Neurotoxins) đã được chứng minh phá hủy tế bào thần kinh, làm suy giảm trí tuệ và gây viêm mạn tính. Mặc dù chưa có bằng chứng khẳng định kim loại nặng là nguyên nhân trực tiếp gây u não, nhưng chúng gây đột biến cấu trúc tế bào và tổn hại nghiêm trọng hệ thần kinh trung ương. Gia đình nên sử dụng nguồn nước sạch qua hệ thống lọc đạt chuẩn y tế được kiểm định.', 'World Health Organization & NIEHS (Hoa Kỳ) — Tác động của các kim loại nặng độc hại trong nước uống đến hệ thần kinh con người (https://www.who.int)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Nước uống nhiễm kim loại nặng (chì, asen, thủy ngân) hoặc vi nhựa (microplastics) có liên quan gì đến tổn thương não bộ?');

INSERT INTO faq_documents (title, content, source, category)
SELECT 'Tóm lại, lời khuyên y khoa chuẩn mực và thực tế nhất để bảo vệ sức khỏe não bộ và phòng tránh bệnh tật là gì?', 'Lời khuyên toàn diện từ các chuyên gia thần kinh học thế giới: (1) Tránh các yếu tố nguy cơ đã biết: hạn chế tiếp xúc bức xạ ion hóa không cần thiết, bỏ thuốc lá để ngừa ung thư di căn não, trang bị bảo hộ lao động khi làm việc với hóa chất; (2) Nuôi dưỡng tế bào não: ăn theo chế độ Địa Trung Hải (nhiều rau xanh, cá béo Omega-3), ngủ sâu 7-8 tiếng/đêm giúp hệ Glymphatic dọn độc tố; (3) Vận động thể chất ít nhất 150 phút/tuần và duy trì tinh thần lạc quan; (4) Đi khám chuyên khoa Thần kinh ngay khi xuất hiện dấu hiệu cảnh báo (đau đầu buổi sáng tăng dần, nhìn đôi, co giật, yếu tay chân); (5) Tuyệt đối không tin theo các mẹo dân gian truyền miệng hoặc thực dưỡng cực đoan.', 'Tisch Brain Tumor Center - Duke University, Mayo Clinic & Vinmec — Khuyến cáo y khoa toàn diện về bảo vệ sức khỏe hệ thần kinh và nhận biết sớm u não (https://tischbraintumorcenter.duke.edu/blog/what-glioma-brain-tumor-everything-you-need-know-0)', 'prevention_risk'
WHERE NOT EXISTS (SELECT 1 FROM faq_documents WHERE title = 'Tóm lại, lời khuyên y khoa chuẩn mực và thực tế nhất để bảo vệ sức khỏe não bộ và phòng tránh bệnh tật là gì?');

